/* ---------- শিক্ষার্থীর বার্ষিক খরচ (ভর্তি থেকে পুরো বছর) ---------- */
const DEFAULT_COST_TYPES = [
  { id: "ct-admission", name: "ভর্তি ফি", amount: 5000 },
  { id: "ct-uniform", name: "পোশাক / ইউনিফর্ম", amount: 2500 },
  { id: "ct-tuition", name: "টিউশন ফি (বার্ষিক)", amount: 12000 },
  { id: "ct-stationary", name: "স্টেশনারি (খাতা, কলম ও সহায়ক সামগ্রী)", amount: 1500 },
  { id: "ct-exam", name: "পরীক্ষা ফি", amount: 2000 },
  { id: "ct-sports", name: "ক্রীড়া ফি", amount: 800 },
  { id: "ct-festival", name: "উৎসব ফি", amount: 700 },
  { id: "ct-transport", name: "পরিবহন ফি", amount: 6000 },
  { id: "ct-library", name: "লাইব্রেরি ফি", amount: 500 },
  { id: "ct-lab", name: "ল্যাব / কম্পিউটার ফি", amount: 1500 },
  { id: "ct-development", name: "উন্নয়ন ফি", amount: 1000 }
];
function defaultCostTypes() { return DEFAULT_COST_TYPES.map(t => ({ ...t })); }
function costTypesOf(data) { return data && data.costTypes && data.costTypes.length ? data.costTypes : DEFAULT_COST_TYPES; }
function costsForStudent(data, sid) {
  const own = ((data && data.studentCosts) || []).filter(c => c.studentId === sid);
  if (own.length) return own;
  return costTypesOf(data).map(t => ({ id: sid + "-" + t.id, studentId: sid, costTypeId: t.id, name: t.name, amount: +t.amount || 0, paid: 0 }));
}
function costTotalsOf(list) { const total = (list || []).reduce((a, c) => a + (+c.amount || 0), 0); const paid = (list || []).reduce((a, c) => a + (+c.paid || 0), 0); return { total, paid, due: Math.max(0, total - paid) }; }
function makeStudentCosts(sid, types, paidTotal) {
  let rem = +paidTotal || 0;
  return (types || []).map(t => { const amt = +t.amount || 0; const pay = Math.min(amt, rem); rem -= pay; return { id: sid + "-" + t.id, studentId: sid, costTypeId: t.id, name: t.name, amount: amt, paid: pay }; });
}
function yearlyTotals(data) {
  const acc = { total: 0, paid: 0, due: 0 };
  ((data && data.students) || []).forEach(x => { const t = costTotalsOf(costsForStudent(data, x.id)); acc.total += t.total; acc.paid += t.paid; acc.due += t.due; });
  return acc;
}
