function Landing({ data, goConsole, openLogin, openAdmission, toast }) {
  const s = data.settings;
  const [slide, setSlide] = useState(0);
  const [page, setPage] = useState("home"); // home | notices | teachers | principal | contact
  const tRef = useRef(null);
  useEffect(() => {
    const t = setInterval(() => setSlide(p => (p + 1) % SLIDES.length), 4500);
    return () => clearInterval(t);
  }, []);
  const issued = data.loans.filter(l => !l.returned).length;
  const stats = [
    { n: data.students.length, l: "মোট শিক্ষার্থী" },
    { n: data.teachers.length, l: "শিক্ষকবৃন্দ" },
    { n: data.classes.length, l: "শ্রেণি" },
    { n: data.books.reduce((a, b) => a + (+b.copies || 0), 0), l: "লাইব্রেরির বই" }
  ];
  const navTo = p => { setPage(p); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const teacherScroll = dir => { if (tRef.current) tRef.current.scrollBy({ left: dir * 250, behavior: "smooth" }); };

  const NoticesBlock = ({ full }) => (
    <div className="card">
      {data.notices.length === 0 && <div className="empty"><b>কোনো নোটিশ নেই</b>কনসোল থেকে নোটিশ যোগ করলে এখানে দেখা যাবে।</div>}
      {(full ? data.notices : data.notices.slice(0, 4)).map(n => (
        <div className="notice-item" key={n.id}>
          <div className="notice-date">{new Date(n.date + "T00:00:00").getDate()}<small>{new Date(n.date + "T00:00:00").toLocaleDateString("bn-BD", { month: "short" })}</small></div>
          <div><h3>{n.title}</h3><p>{n.body}</p></div>
        </div>
      ))}
    </div>
  );

  const TeachersBlock = () => (
    <div>
      {data.teachers.length === 0
        ? <div className="card empty"><b>শিক্ষক তালিকা খালি</b>কনসোল থেকে শিক্ষক যোগ করলে এখানে ছবিসহ স্লাইডারে দেখা যাবে।</div>
        : <div className="t-slider">
            <div className="t-track" ref={tRef}>
              {data.teachers.map(t => (
                <div className="t-card" key={t.id}>
                  {t.photo ? <img src={t.photo} alt={t.name} /> : <div className="t-avatar">{t.name.trim().charAt(0)}</div>}
                  <h3>{t.name}</h3><p>{t.subject}</p><p>{t.qualification}</p>
                </div>
              ))}
            </div>
            <div className="t-nav">
              <button className="icon-btn" onClick={() => teacherScroll(-1)} aria-label="আগের শিক্ষক">‹</button>
              <button className="icon-btn" onClick={() => teacherScroll(1)} aria-label="পরের শিক্ষক">›</button>
            </div>
          </div>}
    </div>
  );

  const PrincipalBlock = () => (
    <div className="card principal">
      <div className="p-ava">{(s.principalName || "প্র").trim().charAt(0)}</div>
      <div>
        <blockquote>“{s.principalMsg}”</blockquote>
        <div className="p-name">{s.principalName || "প্রধান শিক্ষক"}</div>
        <div className="p-role">প্রধান শিক্ষক, {s.name}</div>
      </div>
    </div>
  );

  const ContactBlock = () => (
    <div className="grid2">
      <div className="card">
        <h3 style={{ marginTop: 0 }}>ঠিকানা ও যোগাযোগ</h3>
        <p><b>ঠিকানা:</b> {s.address || "—"}</p>
        <p><b>মোবাইল:</b> {s.phone || "—"}</p>
        <p><b>ইমেইল:</b> {s.email || "—"}</p>
        {s.established && <p><b>প্রতিষ্ঠা:</b> {s.established}</p>}
        <div className="socials">
          {s.fb && <a href={s.fb} target="_blank" rel="noreferrer" aria-label="Facebook"><Icon d={IC.fb} size={19} /></a>}
          {s.yt && <a href={s.yt} target="_blank" rel="noreferrer" aria-label="YouTube"><Icon d={IC.yt} size={19} /></a>}
          {s.ig && <a href={s.ig} target="_blank" rel="noreferrer" aria-label="Instagram"><Icon d={IC.ig} size={19} /></a>}
        </div>
      </div>
      <div className="card">
        <h3 style={{ marginTop: 0 }}>অনলাইন ভর্তি</h3>
        <p style={{ color: "var(--ink2)" }}>ঘরে বসেই ভর্তির আবেদন করুন। আবেদন স্কুল কর্তৃপক্ষ যাচাই করে অনুমোদন দিলে শিক্ষার্থী তালিকায় নাম যুক্ত হবে।</p>
        <button className="btn btn-brand" onClick={openAdmission}>ভর্তির আবেদন করুন</button>
      </div>
    </div>
  );

  return (
    <div>
      <div className="topbar"><div className="wrap">
        <span>{s.address || "আমাদের স্কুলে স্বাগতম"}</span>
        <span>{s.phone ? "☎ " + s.phone : ""}{s.email ? " · ✉ " + s.email : ""}</span>
      </div></div>

      <header className="site-head"><div className="wrap">
        <div className="logo-badge">🎓</div>
        <div>
          <h1 className="school-name">{s.name}</h1>
          <p className="school-motto">{s.motto}{s.established ? " · স্থাপিত: " + s.established : ""}</p>
        </div>
        <div className="head-actions">
          <button className="btn btn-ghost" onClick={goConsole}>কনসোল</button>
          <button className="btn btn-brand" onClick={openLogin}>লগইন করুন</button>
        </div>
      </div></header>

      <nav className="mainnav"><div className="wrap">
        <button className={page === "home" ? "on" : ""} onClick={() => navTo("home")}>হোম</button>
        <button className={page === "principal" ? "on" : ""} onClick={() => navTo("principal")}>প্রধানের বার্তা</button>
        <button className={page === "teachers" ? "on" : ""} onClick={() => navTo("teachers")}>শিক্ষকবৃন্দ</button>
        <button className={page === "notices" ? "on" : ""} onClick={() => navTo("notices")}>নোটিশ বোর্ড</button>
        <button className={page === "contact" ? "on" : ""} onClick={() => navTo("contact")}>যোগাযোগ</button>
        <button onClick={openAdmission}>অনলাইন ভর্তি</button>
      </div></nav>

      {page === "home" && <React.Fragment>
        <div className="slideshow">
          <div className="track" style={{ transform: "translateX(-" + slide * 100 + "%)" }}>
            {SLIDES.map((sl, i) => (
              <div className="slide" key={i}>
                <img src={sl.src} alt={sl.title} />
                <div className="cap"><h2>{sl.title}</h2><p>{sl.text}</p></div>
              </div>
            ))}
          </div>
          <button className="slide-arrow prev" onClick={() => setSlide((slide - 1 + SLIDES.length) % SLIDES.length)} aria-label="আগের ছবি">‹</button>
          <button className="slide-arrow next" onClick={() => setSlide((slide + 1) % SLIDES.length)} aria-label="পরের ছবি">›</button>
          <div className="slide-dots">{SLIDES.map((_, i) => <button key={i} className={i === slide ? "on" : ""} onClick={() => setSlide(i)} aria-label={"ছবি " + (i + 1)} />)}</div>
        </div>

        <div className="wrap">
          <div className="stats-band"><div className="grid">
            {stats.map((st, i) => <div className="stat" key={i}><b>{st.n}</b><span>{st.l}</span></div>)}
          </div></div>

          <section className="section">
            <div className="sec-head"><h2>কেন আমাদের স্কুল</h2><p>শিক্ষার্থীদের সর্বাঙ্গীণ বিকাশে আমরা প্রতিশ্রুতিবদ্ধ</p></div>
            <div className="grid4">
              {[
                { ic: IC.users, t: "অভিজ্ঞ শিক্ষকমণ্ডলী", p: "প্রশিক্ষণপ্রাপ্ত ও যত্নশীল শিক্ষকদের তত্ত্বাবধানে প্রতিটি পাঠ।" },
                { ic: IC.book, t: "সমৃদ্ধ লাইব্রেরি", p: "পাঠ্যবইয়ের পাশাপাশি গল্প, বিজ্ঞান ও সাধারণ জ্ঞানের বিশাল সংগ্রহ।" },
                { ic: IC.flask, t: "বিজ্ঞানাগার ও ল্যাব", p: "হাতে-কলমে শেখার জন্য আধুনিক বিজ্ঞানাগার ও কম্পিউটার ল্যাব।" },
                { ic: IC.award, t: "ধারাবাহিক সাফল্য", p: "বোর্ড পরীক্ষা ও সহশিক্ষা কার্যক্রমে নিয়মিত উল্লেখযোগ্য সাফল্য।" }
              ].map((w, i) => (
                <div className="card why-item" key={i}>
                  <div className="why-ic"><Icon d={w.ic} /></div><h3>{w.t}</h3><p>{w.p}</p>
                </div>
              ))}
            </div>
          </section>

          <section className="section">
            <div className="sec-head"><h2>ক্যাম্পাসের ঝলক</h2></div>
            <div className="gallery">
              <figure><img src="data:image/jpeg;base64," alt="শ্রেণিকক্ষে পাঠদান" /><figcaption>প্রাণবন্ত শ্রেণিকক্ষ</figcaption></figure>
              <figure><img src="data:image/jpeg;base64," alt="স্কুল লাইব্রেরি" /><figcaption>সমৃদ্ধ লাইব্রেরি</figcaption></figure>
              <figure><img src="data:image/jpeg;base64," alt="বিজ্ঞানাগারে পরীক্ষা" /><figcaption>আধুনিক বিজ্ঞানাগার</figcaption></figure>
            </div>
          </section>

          <section className="section">
            <div className="sec-head"><h2>প্রধানের বার্তা</h2></div>
            <PrincipalBlock />
          </section>

          <section className="section">
            <div className="sec-head"><h2>শিক্ষকবৃন্দ</h2><p>ছবিসহ স্লাইডার — পাশে টেনে বা তীর চাপুন</p></div>
            <TeachersBlock />
          </section>

          <section className="section">
            <div className="sec-head"><h2>নোটিশ বোর্ড</h2>
              <button className="btn btn-ghost btn-sm" onClick={() => navTo("notices")}>সব নোটিশ দেখুন</button></div>
            <NoticesBlock full={false} />
          </section>

          <section className="section">
            <div className="sec-head"><h2>শ্রেণিসমূহ</h2></div>
            {data.classes.length === 0
              ? <div className="card empty"><b>শ্রেণি তথ্য নেই</b>কনসোল থেকে শ্রেণি যোগ করলে এখানে দেখা যাবে।</div>
              : <div className="grid3">{data.classes.map(c => (
                  <div className="card" key={c.id}><h3 style={{ margin: "0 0 4px" }}>{c.name} শ্রেণি</h3>
                    <p style={{ margin: 0, color: "var(--ink2)", fontSize: "14.5px" }}>শাখা: {c.sections || "—"} · কক্ষ: {c.room || "—"} · আসন: {c.capacity || "—"}<br />শিক্ষার্থী: {data.students.filter(x => x.cls === c.name).length} জন</p></div>
                ))}</div>}
          </section>

          <div className="admit-banner">
            <img src="data:image/jpeg;base64," alt="ভর্তি চলছে" />
            <div className="in">
              <h2>ভর্তি চলছে!</h2>
              <p>নতুন শিক্ষাবর্ষে সীমিত আসনে ভর্তি চলছে। আজই অনলাইনে আবেদন করুন।</p>
              {s.showYearlyCostAtAdmission !== false && <p style={{ fontWeight: 700, color: "#fff" }}>ভর্তি থেকে পুরো বছরের মোট খরচ: {taka(costTypesOf(data).reduce((a, t) => a + (+t.amount || 0), 0))} — খাতভিত্তিক তালিকা ভর্তি ফরমে দেখা যাবে</p>}
              <div><button className="btn btn-accent" onClick={openAdmission}>এখনই আবেদন করুন</button></div>
            </div>
          </div>

          <section className="section"><ContactBlock /></section>
        </div>
      </React.Fragment>}

      {page === "notices" && <div className="wrap"><section className="section">
        <div className="sec-head"><h2>নোটিশ বোর্ড</h2><p>স্কুলের সব ঘোষণা</p></div><NoticesBlock full={true} />
      </section></div>}

      {page === "teachers" && <div className="wrap"><section className="section">
        <div className="sec-head"><h2>শিক্ষকবৃন্দ</h2><p>আমাদের শিক্ষকদের পরিচিতি</p></div><TeachersBlock />
        <div className="grid3" style={{ marginTop: 16 }}>
          {data.teachers.map(t => <div className="card" key={t.id}><h3 style={{ margin: "0 0 3px" }}>{t.name}</h3><p style={{ margin: 0, color: "var(--ink2)", fontSize: "14.5px" }}>বিষয়: {t.subject}<br />যোগ্যতা: {t.qualification}<br />মোবাইল: {t.phone}</p></div>)}
        </div>
      </section></div>}

      {page === "principal" && <div className="wrap"><section className="section">
        <div className="sec-head"><h2>প্রধানের বার্তা</h2></div><PrincipalBlock />
      </section></div>}

      {page === "contact" && <div className="wrap"><section className="section">
        <div className="sec-head"><h2>যোগাযোগ</h2></div><ContactBlock />
      </section></div>}

      <footer className="site-foot"><div className="wrap">
        <div className="cols">
          <div>
            <h3>{s.name}</h3>
            <p>{s.motto}</p>
            <p>শিক্ষার্থীদের জ্ঞান, চরিত্র ও দক্ষতায় গড়ে তোলাই আমাদের অঙ্গীকার।</p>
            <div className="socials">
              {s.fb && <a href={s.fb} target="_blank" rel="noreferrer" aria-label="Facebook"><Icon d={IC.fb} size={18} /></a>}
              {s.yt && <a href={s.yt} target="_blank" rel="noreferrer" aria-label="YouTube"><Icon d={IC.yt} size={18} /></a>}
              {s.ig && <a href={s.ig} target="_blank" rel="noreferrer" aria-label="Instagram"><Icon d={IC.ig} size={18} /></a>}
              {!s.fb && !s.yt && !s.ig && <span style={{ fontSize: "13.5px" }}>সোশ্যাল লিংক সেটিংস থেকে যোগ করুন</span>}
            </div>
          </div>
          <div>
            <h3>দ্রুত লিংক</h3>
            <ul className="foot-links">
              <li><button onClick={() => navTo("home")}>হোম</button></li>
              <li><button onClick={() => navTo("notices")}>নোটিশ বোর্ড</button></li>
              <li><button onClick={() => navTo("teachers")}>শিক্ষকবৃন্দ</button></li>
              <li><button onClick={() => navTo("principal")}>প্রধানের বার্তা</button></li>
              <li><button onClick={openAdmission}>অনলাইন ভর্তি</button></li>
              <li><button onClick={openLogin}>লগইন</button></li>
            </ul>
          </div>
          <div>
            <h3>ঠিকানা</h3>
            <p>{s.address || "—"}</p>
            <p>মোবাইল: {s.phone || "—"}</p>
            <p>ইমেইল: {s.email || "—"}</p>
          </div>
        </div>
        <div className="foot-bottom">
          <span>© {s.name} — সর্বস্বত্ব সংরক্ষিত</span>
        </div>
      </div></footer>
    </div>
  );
}

/* ================================================================
   লগইন — ডেমো লগইন (আগের সিস্টেম)
   অ্যাডমিন / শিক্ষক ও শিক্ষার্থী ট্যাব, সুপার অ্যাডমিন আইডি বসানোর
   বোতাম; যেকোনো পাসওয়ার্ড দিলেই কনসোল খোলে — পাসওয়ার্ড যাচাই হয় না।
   কোনো সার্ভার লগইন বা পাসওয়ার্ড যাচাই নেই।
================================================================ */
const SUPER_ADMIN_ID = "sizubd333@gmail.com";

function LoginModal({ close, onLogin }) {
  const [role, setRole] = useState("admin");
  const [id, setId] = useState("");
  const [pass, setPass] = useState("");
  const [year, setYear] = useState("২০২৬");
  const submit = e => {
    e.preventDefault();
    if (!id.trim() || !pass.trim()) return;
    onLogin({ role, id: id.trim(), isSuper: id.trim().toLowerCase() === SUPER_ADMIN_ID, via: "demo" });
  };
  return (
    <div className="modal-bg" onClick={e => { if (e.target === e.currentTarget) close(); }}>
      <form className="modal" onSubmit={submit}>
        <h2>লগইন করুন</h2>
        <p className="sub">আপনার ভূমিকা বেছে নিয়ে আইডি ও পাসওয়ার্ড দিয়ে কনসোলে প্রবেশ করুন।</p>
        <div className="role-tabs">
          <button type="button" className={role === "admin" ? "on" : ""} onClick={() => setRole("admin")}>অ্যাডমিন / শিক্ষক</button>
          <button type="button" className={role === "student" ? "on" : ""} onClick={() => setRole("student")}>শিক্ষার্থী</button>
        </div>
        {role === "student" && (
          <div style={{ marginBottom: 12 }}>
            <label>শিক্ষাবর্ষ</label>
            <select value={year} onChange={e => setYear(e.target.value)}>
              <option>২০২৬</option><option>২০২৫</option><option>২০২৪</option>
            </select>
          </div>
        )}
        <div style={{ marginBottom: 12 }}>
          <label>{role === "student" ? "শিক্ষার্থী আইডি" : "ইউজার আইডি / ইমেইল"}</label>
          <input type="text" value={id} onChange={e => setId(e.target.value)} placeholder={role === "student" ? "যেমন: 101" : "আপনার আইডি লিখুন"} autoComplete="username" />
        </div>
        <div>
          <label>পাসওয়ার্ড</label>
          <input type="password" value={pass} onChange={e => setPass(e.target.value)} placeholder="পাসওয়ার্ড লিখুন" autoComplete="current-password" />
        </div>
        <button type="button" className="btn btn-ghost btn-block" style={{ marginTop: 12 }}
          onClick={() => { setRole("admin"); setId(SUPER_ADMIN_ID); }}>
          সুপার অ্যাডমিন আইডি বসান ({SUPER_ADMIN_ID})
        </button>
        <div className="note-box">
          <b>ডেমো লগইন:</b> যেকোনো পাসওয়ার্ড দিলেই কনসোল খুলবে — পাসওয়ার্ড যাচাই হয় না। সুপার অ্যাডমিন ইমেইল দিয়ে লগইন করলে কনসোলে সুপার অ্যাডমিন চিপ দেখাবে।
        </div>
        <div style={{ display: "flex", gap: 9, flexWrap: "wrap" }}>
          <button type="submit" className="btn btn-brand" style={{ flex: 1 }}>লগইন করে কনসোল খুলুন</button>
          <button type="button" className="btn btn-ghost" onClick={close}>বন্ধ করুন</button>
        </div>
      </form>
    </div>
  );
}

/* ---------- অনলাইন ভর্তির আবেদন ---------- */
function AdmissionModal({ close, submit, showCost, costTypes }) {
  const [f, setF] = useState({ name: "", cls: "ষষ্ঠ", guardian: "", phone: "", address: "" });
  const set = k => e => setF({ ...f, [k]: e.target.value });
  const [syncMsg, setSyncMsg] = useState("");
  const doSync = () => { setSyncMsg("সিঙ্ক হয়নি — এখন অফলাইন / লোকাল মোডে আছে। ডেটা এই ব্রাউজারেই আছে; পরে আবার চেষ্টা করুন।"); };
  return (
    <div className="modal-bg" onClick={e => { if (e.target === e.currentTarget) close(); }}>
      <form className="modal" onSubmit={e => { e.preventDefault(); if (f.name.trim()) submit(f); }}>
        <h2>অনলাইন ভর্তির আবেদন</h2>
        <p className="sub">তথ্য পূরণ করে জমা দিন। স্কুল কর্তৃপক্ষ যাচাই করে সিদ্ধান্ত জানাবে।</p>
        {showCost && costTypes && costTypes.length > 0 && (
          <div className="note-box" style={{ marginTop: 0 }}>
            <b>ভর্তি থেকে পুরো বছরের খরচের তালিকা</b>
            {costTypes.map(t => <div key={t.id} style={{ display: "flex", justifyContent: "space-between", gap: 10 }}><span>{t.name}</span><b>{taka(t.amount)}</b></div>)}
            <div style={{ display: "flex", justifyContent: "space-between", gap: 10, borderTop: "1px solid var(--line)", marginTop: 6, paddingTop: 6 }}><span><b>মোট বার্ষিক খরচ</b></span><b>{taka(costTypes.reduce((a, t) => a + (+t.amount || 0), 0))}</b></div>
          </div>
        )}
        <div className="form-grid">
          <div className="full"><label>শিক্ষার্থীর নাম *</label><input value={f.name} onChange={set("name")} required /></div>
          <div><label>ভর্তিচ্ছু শ্রেণি</label>
            <select value={f.cls} onChange={set("cls")}>{CLASS_NAMES.map(c => <option key={c}>{c}</option>)}</select></div>
          <div><label>অভিভাবকের নাম</label><input value={f.guardian} onChange={set("guardian")} /></div>
          <div><label>মোবাইল নম্বর</label><input value={f.phone} onChange={set("phone")} /></div>
          <div><label>ঠিকানা</label><input value={f.address} onChange={set("address")} /></div>
        </div>
        <div style={{ display: "flex", gap: 9, marginTop: 16, flexWrap: "wrap" }}>
          <button type="submit" className="btn btn-brand" style={{ flex: 1 }}>আবেদন জমা দিন</button>
          <button type="button" className="btn btn-ghost" onClick={close}>বন্ধ করুন</button>
        </div>
      </form>
    </div>
  );
}

/* ================================================================
   অ্যাডমিন কনসোল — স্কুলের ১৩টি + অফিস ম্যানেজমেন্টের ৯টি মডিউল
================================================================ */
const MODULES = [
  { id: "dashboard", label: "ড্যাশবোর্ড", icon: "▦" },
  { id: "students", label: "শিক্ষার্থী", icon: "🎓" },
  { id: "teachers", label: "শিক্ষক", icon: "👩‍🏫" },
  { id: "classes", label: "শ্রেণি ও বিষয়", icon: "🏫" },
  { id: "attendance", label: "হাজিরা", icon: "✓" },
  { id: "results", label: "পরীক্ষা ও ফলাফল", icon: "📊" },
  { id: "fees", label: "ফি ও বকেয়া", icon: "💰" },
  { id: "notices", label: "নোটিশ", icon: "📢" },
  { id: "routine", label: "ক্লাস রুটিন", icon: "🕐" },
  { id: "library", label: "লাইব্রেরি", icon: "📚" },
  { id: "transport", label: "পরিবহন", icon: "🚌" },
  { id: "admissions", label: "ভর্তি আবেদন", icon: "📝" },
  { id: "employees", label: "অফিস কর্মী", icon: "🧑‍💼", office: true },
  { id: "departments", label: "বিভাগসমূহ", icon: "🏢", office: true },
  { id: "office-attendance", label: "অফিস হাজিরা", icon: "🗓", office: true },
  { id: "leaves", label: "ছুটি ব্যবস্থাপনা", icon: "🌴", office: true },
  { id: "payroll", label: "বেতন / পেরোল", icon: "💵", office: true },
  { id: "tasks", label: "অফিসের কাজ", icon: "✅", office: true },
  { id: "expenses", label: "অফিস খরচ", icon: "🧾", office: true },
  { id: "student-costs", label: "শিক্ষার্থীর বার্ষিক খরচ", icon: "🧮", office: true },
  { id: "office-docs", label: "নথি ও অফিস নোটিশ", icon: "🗂", office: true },
  { id: "settings", label: "সেটিংস", icon: "⚙" },
];

function Field({ label, children, full }) {
  return <div className={full ? "full" : ""}><label>{label}</label>{children}</div>;
}
function ModalForm({ title, sub, close, onSubmit, children, submitLabel }) {
  return (
    <div className="modal-bg" onClick={e => { if (e.target === e.currentTarget) close(); }}>
      <form className="modal wide" onSubmit={e => { e.preventDefault(); onSubmit(); }}>
        <h2>{title}</h2>{sub && <p className="sub">{sub}</p>}
        <div className="form-grid">{children}</div>
        <div style={{ display: "flex", gap: 9, marginTop: 16, flexWrap: "wrap" }}>
          <button type="submit" className="btn btn-brand" style={{ flex: 1 }}>{submitLabel || "সংরক্ষণ করুন"}</button>
          <button type="button" className="btn btn-ghost" onClick={close}>বাতিল</button>
        </div>
      </form>
    </div>
  );
}

function Console({ data, setData, user, logout, goLanding, toast }) {
  const [mod, setMod] = useState("dashboard");
  const [search, setSearch] = useState("");
  const [editStudent, setEditStudent] = useState(null);
  const [showStudentForm, setShowStudentForm] = useState(false);
  const [teacherForm, setTeacherForm] = useState(false);
  const [classForm, setClassForm] = useState(false);
  const [subjectForm, setSubjectForm] = useState(false);
  const [noticeForm, setNoticeForm] = useState(false);
  const [bookForm, setBookForm] = useState(false);
  const [routeForm, setRouteForm] = useState(false);
  const [attClass, setAttClass] = useState("ষষ্ঠ");
  const [attDate, setAttDate] = useState(todayStr());
  const [attDraft, setAttDraft] = useState(null);
  const [resStudent, setResStudent] = useState("");
  const [marks, setMarks] = useState({});
  const [payFor, setPayFor] = useState(null);
  const [payAmt, setPayAmt] = useState("");
  const [loanForm, setLoanForm] = useState(false);
  const [editEmp, setEditEmp] = useState(null);
  const [empForm, setEmpForm] = useState(false);
  const [deptForm, setDeptForm] = useState(false);
  const [leaveForm, setLeaveForm] = useState(false);
  const [payrollForm, setPayrollForm] = useState(false);
  const [taskForm, setTaskForm] = useState(false);
  const [expenseForm, setExpenseForm] = useState(false);
  const [docForm, setDocForm] = useState(false);
  const [oAttDate, setOAttDate] = useState(todayStr());
  const [oAttDraft, setOAttDraft] = useState(null);
  const [payMonth, setPayMonth] = useState(todayStr().slice(0, 7));
  const [costStudentId, setCostStudentId] = useState("");
  const [costTypeForm, setCostTypeForm] = useState(false);
  const [editCostType, setEditCostType] = useState(null);
  const [costItemEdit, setCostItemEdit] = useState(null);
  const [costItemAdd, setCostItemAdd] = useState(null);
  const [costPayFor, setCostPayFor] = useState(null);
  const [costPayAmt, setCostPayAmt] = useState("");
  const [photoErr, setPhotoErr] = useState("");

  const S = data.settings;
  const collected = data.students.reduce((a, x) => a + (+x.paid || 0), 0);
  const dues = data.students.reduce((a, x) => a + Math.max(0, (+x.payable || 0) - (+x.paid || 0)), 0);
  const pendingAdm = data.admissions.filter(a => a.status === "pending");
  const issuedLoans = data.loans.filter(l => !l.returned);
  const pendingLeaves = data.leaves.filter(l => l.status === "pending");
  const empName = id => { const e = data.employees.find(x => x.id === id); return e ? e.name : "—"; };
  const oAttMap = oAttDraft && oAttDraft.key === oAttDate ? oAttDraft.map : (data.officeAttendance[oAttDate] || {});
  const toggleOAtt = id => { const cur = oAttMap[id] || "P"; setOAttDraft({ key: oAttDate, map: { ...oAttMap, [id]: cur === "P" ? "A" : "P" } }); };
  const saveOAtt = () => { const full = {}; data.employees.forEach(x => { full[x.id] = oAttMap[x.id] || "P"; }); patch({ officeAttendance: { ...data.officeAttendance, [oAttDate]: full } }); setOAttDraft(null); toast("অফিস হাজিরা সংরক্ষিত হয়েছে — " + bnDate(oAttDate)); };
  const monthPayroll = data.payroll.filter(x2 => x2.month === payMonth);
  const monthPayTotal = monthPayroll.reduce((a, x2) => a + (+x2.basic || 0) + (+x2.allowance || 0) - (+x2.deduction || 0), 0);
  const officeExpTotal = data.expenses.reduce((a, x2) => a + (+x2.amount || 0), 0);
  const empList = data.employees.filter(x => !search || x.name.includes(search) || (x.dept || "").includes(search));
  const saveEmp = f => {
    const rec = { ...f, salary: +f.salary || 0 };
    if (editEmp) { patch({ employees: data.employees.map(x => x.id === editEmp.id ? { ...rec, id: editEmp.id } : x) }); toast("কর্মীর তথ্য আপডেট হয়েছে"); }
    else { patch({ employees: [...data.employees, { ...rec, id: uid() }] }); toast("নতুন অফিস কর্মী যোগ হয়েছে"); }
    setEmpForm(false); setEditEmp(null);
  };
  const patch = p => setData(prev => ({ ...prev, ...p }));

  /* ----- শিক্ষার্থীর বার্ষিক খরচ ----- */
  const costTypes = costTypesOf(data);
  const showCostAtAdmission = S.showYearlyCostAtAdmission !== false;
  const costsOf = sid => costsForStudent(data, sid);
  const yearly = yearlyTotals(data);
  const yearlyPerStudent = costTypes.reduce((a, t) => a + (+t.amount || 0), 0);
  const updateStudentCosts = (sid, list) => {
    const t = costTotalsOf(list);
    patch({ studentCosts: [...(data.studentCosts || []).filter(c => c.studentId !== sid), ...list],
            students: data.students.map(x => x.id === sid ? { ...x, payable: t.total, paid: t.paid } : x) });
  };
  const saveCostType = f => {
    if (!f.name || !f.name.trim()) return;
    if (editCostType) {
      patch({ costTypes: costTypes.map(t => t.id === editCostType.id ? { ...t, name: f.name, amount: +f.amount || 0 } : t),
              studentCosts: (data.studentCosts || []).map(c => c.costTypeId === editCostType.id ? { ...c, name: f.name } : c) });
      toast("খরচের ধরন আপডেট হয়েছে");
    } else {
      patch({ costTypes: [...costTypes, { id: uid(), name: f.name, amount: +f.amount || 0, isCustom: true }] });
      toast("নতুন কাস্টম খরচের ধরন যোগ হয়েছে");
    }
    setCostTypeForm(false); setEditCostType(null);
  };
  const delCostType = t => { patch({ costTypes: costTypes.filter(x => x.id !== t.id) }); toast("খরচের ধরন মোছা হয়েছে — আগের শিক্ষার্থীদের হিসাব অপরিবর্তিত আছে"); };
  const saveCostPay = () => {
    const amt = parseFloat(costPayAmt) || 0; if (amt <= 0 || !costPayFor) return;
    const list = costsOf(costPayFor.studentId).map(c => c.id === costPayFor.id ? { ...c, paid: Math.min(+c.amount || 0, (+c.paid || 0) + amt) } : c);
    updateStudentCosts(costPayFor.studentId, list);
    setCostPayFor(null); setCostPayAmt(""); toast("খরচের জমা নেওয়া হয়েছে: " + taka(amt));
  };
  const downloadCostSheet = st => {
    const list = costsOf(st.id); const t = costTotalsOf(list);
    const rows = list.map(c => "<tr><td>" + c.name + "</td><td>" + taka(c.amount) + "</td><td>" + taka(c.paid) + "</td><td>" + taka(Math.max(0, (+c.amount || 0) - (+c.paid || 0))) + "</td></tr>").join("");
    const html = "<!doctype html><html lang='bn'><head><meta charset='utf-8'><title>বার্ষিক খরচের তালিকা</title><style>body{font-family:sans-serif;padding:30px;color:#222}table{border-collapse:collapse;width:100%}td,th{border:1px solid #999;padding:8px}h1{text-align:center;margin-bottom:2px}p{text-align:center}</style></head><body><h1>" + S.name + "</h1><p>" + S.motto + "</p><h3>শিক্ষার্থীর বার্ষিক খরচের তালিকা</h3><p style='text-align:left'>নাম: <b>" + st.name + "</b> · শ্রেণি: " + st.cls + " · রোল: " + st.roll + " · শাখা: " + (st.section || "ক") + "</p><table><tr><th>খরচের খাত</th><th>পরিমাণ</th><th>জমা</th><th>বকেয়া</th></tr>" + rows + "</table><p style='text-align:left'><b>মোট বার্ষিক খরচ: " + taka(t.total) + " · জমা: " + taka(t.paid) + " · বকেয়া: " + taka(t.due) + "</b></p></body></html>";
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([html], { type: "text/html;charset=utf-8" }));
    a.download = "yearly-cost-" + st.roll + ".html"; document.body.appendChild(a); a.click(); a.remove();
    toast("বার্ষিক খরচের তালিকা ডাউনলোড হচ্ছে");
  };

  /* ----- শিক্ষার্থী ----- */
  const saveStudent = f => {
    if (f.id) { patch({ students: data.students.map(x => x.id === f.id ? f : x) }); toast("শিক্ষার্থীর তথ্য আপডেট হয়েছে"); }
    else { const nid = uid(); const items = makeStudentCosts(nid, costTypes, 0); const tot = costTotalsOf(items); patch({ students: [...data.students, { ...f, id: nid, payable: tot.total }], studentCosts: [...(data.studentCosts || []), ...items] }); toast("নতুন শিক্ষার্থী যোগ হয়েছে — বার্ষিক খরচের তালিকা তৈরি হয়েছে"); }
    setShowStudentForm(false); setEditStudent(null);
  };
  const delStudent = id => patch({ students: data.students.filter(x => x.id !== id), studentCosts: (data.studentCosts || []).filter(c => c.studentId !== id) });
  const studentList = data.students.filter(x => !search || x.name.includes(search) || String(x.roll).includes(search));

  /* ----- হাজিরা ----- */
  const attKey = attDate + "|" + attClass;
  const attStudents = data.students.filter(x => x.cls === attClass);
  const attMap = attDraft && attDraft.key === attKey ? attDraft.map : (data.attendance[attKey] || {});
  const toggleAtt = id => {
    const cur = attMap[id] || "P";
    setAttDraft({ key: attKey, map: { ...attMap, [id]: cur === "P" ? "A" : "P" } });
  };
  const saveAtt = () => {
    const full = {}; attStudents.forEach(x => { full[x.id] = attMap[x.id] || "P"; });
    patch({ attendance: { ...data.attendance, [attKey]: full } });
    setAttDraft(null); toast("হাজিরা সংরক্ষিত হয়েছে — " + bnDate(attDate));
  };
  const attHistory = Object.keys(data.attendance).sort().reverse();

  /* ----- ফলাফল ----- */
  const resOf = sid => data.results[sid];
  const gpaOf = sid => {
    const r = resOf(sid); if (!r) return null;
    const gs = SUBJECTS.map(sub => gradeOf(+r[sub] || 0));
    if (gs.some(g => g.gpa === 0)) return { gpa: 0, grade: "F" };
    return { gpa: Math.round(gs.reduce((a, g) => a + g.gpa, 0) / gs.length * 100) / 100, grade: gs[0].grade };
  };
  const openMarks = sid => { setResStudent(sid); setMarks(resOf(sid) || {}); };
  const saveMarks = () => { patch({ results: { ...data.results, [resStudent]: marks } }); toast("নম্বর সংরক্ষিত হয়েছে"); };
  const downloadResult = st => {
    const r = resOf(st.id) || {}; const g = gpaOf(st.id);
    const rows = SUBJECTS.map(sub => { const m = +r[sub] || 0; const gr = gradeOf(m); return "<tr><td>" + sub + "</td><td>" + m + "</td><td>" + gr.grade + "</td><td>" + gr.gpa.toFixed(1) + "</td></tr>"; }).join("");
    const html = "<!doctype html><html lang='bn'><head><meta charset='utf-8'><title>ফলাফল শিট</title><style>body{font-family:sans-serif;padding:30px;color:#222}table{border-collapse:collapse;width:100%}td,th{border:1px solid #999;padding:8px}h1{text-align:center;margin-bottom:2px}p{text-align:center}</style></head><body><h1>" + S.name + "</h1><p>" + S.motto + "</p><h3>ফলাফল শিট</h3><p style='text-align:left'>নাম: <b>" + st.name + "</b> · শ্রেণি: " + st.cls + " · রোল: " + st.roll + " · শাখা: " + (st.section || "ক") + "</p><table><tr><th>বিষয়</th><th>নম্বর</th><th>গ্রেড</th><th>জিপি</th></tr>" + rows + "</table><p style='text-align:left'><b>মোট GPA: " + (g ? g.gpa.toFixed(2) : "—") + "</b></p></body></html>";
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([html], { type: "text/html;charset=utf-8" }));
    a.download = "result-" + st.roll + ".html"; document.body.appendChild(a); a.click(); a.remove();
    toast("ফলাফল শিট ডাউনলোড হচ্ছে");
  };

  /* ----- ফি ----- */
  const savePay = () => {
    const amt = parseFloat(payAmt) || 0; if (amt <= 0) return;
    patch({ students: data.students.map(x => x.id === payFor.id ? { ...x, paid: (+x.paid || 0) + amt } : x) });
    setPayFor(null); setPayAmt(""); toast("ফি জমা নেওয়া হয়েছে: " + taka(amt));
  };

  /* ----- ব্যাকআপ ----- */
  const downloadBackup = () => {
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: "application/json;charset=utf-8" }));
    a.download = "school-backup.json"; document.body.appendChild(a); a.click(); a.remove();
    toast("ব্যাকআপ ডাউনলোড হচ্ছে");
  };
  const importBackup = e => {
    const file = e.target.files[0]; if (!file) return;
    const r = new FileReader();
    r.onload = () => { try { const j = JSON.parse(r.result); if (j.settings && Array.isArray(j.students)) { setData({ ...emptyData(), ...j }); toast("ব্যাকআপ আপলোড হয়েছে"); } else toast("ফাইলটি সঠিক ব্যাকআপ নয়", true); } catch (err) { toast("ফাইল পড়া যায়নি", true); } };
    r.readAsText(file); e.target.value = "";
  };
  const onPhoto = (e, cb) => {
    const file = e.target.files[0]; if (!file) return;
    if (file.size > 700 * 1024) { setPhotoErr("ছবি ৭০০KB-এর বেশি — ছোট ছবি দিন।"); return; }
    const r = new FileReader(); r.onload = () => { setPhotoErr(""); cb(r.result); }; r.readAsDataURL(file);
  };

  return (
    <div className="console">
      <aside className="sidebar">
        <div className="s-school">{S.name}</div>
        <div className="s-role">অ্যাডমিন কনসোল</div>
        {user && user.isSuper && <span className="admin-chip">★ সুপার অ্যাডমিন</span>}
        {user && <div className="s-role" style={{ marginTop: 2 }}>{user.id}</div>}
        <nav className="side-nav">
          {MODULES.map(m => (
            <React.Fragment key={m.id}>
              {m.id === "dashboard" && <div className="side-group">🏫 স্কুল ম্যানেজমেন্ট</div>}
              {m.id === "employees" && <div className="side-group">🏢 অফিস ম্যানেজমেন্ট</div>}
              <button className={mod === m.id ? "on" : ""} onClick={() => { setMod(m.id); setSearch(""); }}>
                <span className="ic">{m.icon}</span>{m.label}
                {m.id === "admissions" && pendingAdm.length > 0 && <span className="pill pill-warn" style={{ marginLeft: "auto" }}>{pendingAdm.length}</span>}
                {m.id === "leaves" && pendingLeaves.length > 0 && <span className="pill pill-warn" style={{ marginLeft: "auto" }}>{pendingLeaves.length}</span>}
              </button>
            </React.Fragment>
          ))}
        </nav>
        <div style={{ marginTop: 16, display: "flex", flexDirection: "column", gap: 7 }}>
          <button className="btn btn-light btn-sm" onClick={goLanding}>← পাবলিক পেজ দেখুন</button>
          <button className="btn btn-accent btn-sm" onClick={logout}>লগআউট</button>
        </div>
      </aside>

      <main className="main">
        {mod === "dashboard" && <div>
          <div className="welcome-banner">
            <img src="data:image/jpeg;base64," alt="" />
            <div className="in"><h2>স্বাগতম, {S.name}</h2><p>{S.motto} · আজ {bnDate(todayStr())}</p></div>
          </div>
          <div className="kpis">
            <div className="kpi"><b>{data.students.length}</b><span>মোট শিক্ষার্থী</span></div>
            <div className="kpi"><b>{data.teachers.length}</b><span>শিক্ষক</span></div>
            <div className="kpi"><b>{taka(collected)}</b><span>ফি আদায়</span></div>
            <div className="kpi"><b>{taka(dues)}</b><span>মোট বকেয়া</span></div>
          </div>
          <div className="grid2">
            <div className="card">
              <h3 style={{ marginTop: 0 }}>এক নজরে</h3>
              <p>শ্রেণি: {data.classes.length} · বিষয়: {data.subjects.length} · লাইব্রেরির বই: {data.books.reduce((a, b) => a + (+b.copies || 0), 0)}টি (ধার দেওয়া {issuedLoans.length}টি)</p>
              <p>পরিবহন রুট: {data.routes.length} · অপেক্ষমাণ ভর্তি আবেদন: {pendingAdm.length}টি</p>
              <p>আজকের হাজিরা রেকর্ড: {Object.keys(data.attendance).filter(k => k.startsWith(todayStr())).length}টি শ্রেণি</p>
            </div>
            <div className="card">
              <h3 style={{ marginTop: 0 }}>দ্রুত কাজ</h3>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                <button className="btn btn-brand btn-sm" onClick={() => { setMod("students"); setEditStudent(null); setShowStudentForm(true); }}>+ শিক্ষার্থী যোগ</button>
                <button className="btn btn-ghost btn-sm" onClick={() => setMod("attendance")}>আজকের হাজিরা</button>
                <button className="btn btn-ghost btn-sm" onClick={() => { setMod("notices"); setNoticeForm(true); }}>+ নোটিশ</button>
                <button className="btn btn-ghost btn-sm" onClick={() => setMod("results")}>ফলাফল দিন</button>
              </div>
              {data.students.length === 0 && <div className="note-box">তথ্য এখনো খালি। সেটিংস থেকে এক ক্লিকে <b>নমুনা তথ্য</b> বসিয়ে সব মডিউল ঘুরে দেখতে পারেন, আবার মুছেও ফেলতে পারবেন।</div>}
            </div>
          </div>
          <div className="card" style={{ marginTop: 16 }}>
            <h3 style={{ marginTop: 0 }}>🏢 অফিস ম্যানেজমেন্ট — এক নজরে</h3>
            <p>অফিস কর্মী: {data.employees.length} জন · বিভাগ: {data.departments.length}টি · অপেক্ষমাণ ছুটি: {pendingLeaves.length}টি · চলমান কাজ: {data.tasks.filter(t => t.status !== "সম্পন্ন").length}টি</p>
            <p>নির্বাচিত মাসের ({payMonth}) মোট বেতন: {taka(monthPayTotal)} · মোট অফিস খরচ: {taka(officeExpTotal)} · অফিস নথি/নোটিশ: {data.officeDocs.length}টি</p>
            <p>শিক্ষার্থীদের মোট বার্ষিক খরচ: {taka(yearly.total)} · আদায়: {taka(yearly.paid)} · বকেয়া: {taka(yearly.due)}</p>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              <button className="btn btn-brand btn-sm" onClick={() => { setMod("employees"); setEditEmp(null); setEmpForm(true); }}>+ অফিস কর্মী যোগ</button>
              <button className="btn btn-ghost btn-sm" onClick={() => setMod("office-attendance")}>অফিস হাজিরা</button>
              <button className="btn btn-ghost btn-sm" onClick={() => setMod("leaves")}>ছুটির আবেদন{pendingLeaves.length > 0 ? " (" + pendingLeaves.length + ")" : ""}</button>
              <button className="btn btn-ghost btn-sm" onClick={() => setMod("payroll")}>বেতন শিট</button>
              <button className="btn btn-ghost btn-sm" onClick={() => setMod("expenses")}>অফিস খরচ</button>
              <button className="btn btn-ghost btn-sm" onClick={() => setMod("student-costs")}>শিক্ষার্থীর বার্ষিক খরচ</button>
            </div>
          </div>
          {data.notices.length > 0 && <div className="card" style={{ marginTop: 16 }}>
            <h3 style={{ marginTop: 0 }}>সাম্প্রতিক নোটিশ</h3>
            {data.notices.slice(0, 3).map(n => <div className="notice-item" key={n.id}><div className="notice-date">{new Date(n.date + "T00:00:00").getDate()}<small>{new Date(n.date + "T00:00:00").toLocaleDateString("bn-BD", { month: "short" })}</small></div><div><h3>{n.title}</h3><p>{n.body}</p></div></div>)}
          </div>}
        </div>}

        {mod === "students" && <div>
          <h1>শিক্ষার্থী ব্যবস্থাপনা</h1><p className="lede">মোট {data.students.length} জন শিক্ষার্থী</p>
          <div className="toolbar">
            <input type="search" placeholder="নাম বা রোল খুঁজুন…" value={search} onChange={e => setSearch(e.target.value)} />
            <span className="sp"></span>
            <button className="btn btn-brand" onClick={() => { setEditStudent(null); setShowStudentForm(true); }}>+ নতুন শিক্ষার্থী</button>
          </div>
          {data.students.length === 0
            ? <div className="card empty"><b>কোনো শিক্ষার্থী নেই</b>“নতুন শিক্ষার্থী” বোতামে যোগ করুন, অথবা সেটিংস থেকে নমুনা তথ্য বসান।</div>
            : <div className="table-wrap"><table><thead><tr><th>নাম</th><th>শ্রেণি</th><th>রোল</th><th>শাখা</th><th>অভিভাবক</th><th>মোবাইল</th><th>বকেয়া</th><th>অ্যাকশন</th></tr></thead>
              <tbody>{studentList.map(x => { const due = (+x.payable || 0) - (+x.paid || 0); return (
                <tr key={x.id}><td><b>{x.name}</b></td><td>{x.cls}</td><td>{x.roll}</td><td>{x.section}</td><td>{x.guardian}</td><td>{x.phone}</td>
                <td>{due > 0 ? <span className="pill pill-warn">{taka(due)}</span> : <span className="pill pill-ok">পরিশোধিত</span>}</td>
                <td><div className="row-actions">
                  <button className="mini-btn" onClick={() => { setCostStudentId(x.id); setMod("student-costs"); }}>বার্ষিক খরচ</button>
                  <button className="mini-btn" onClick={() => { setEditStudent(x); setShowStudentForm(true); }}>সম্পাদনা</button>
                  <button className="mini-btn red" onClick={() => delStudent(x.id)}>মুছুন</button>
                </div></td></tr>); })}
              </tbody></table></div>}
        </div>}

        {mod === "teachers" && <div>
          <h1>শিক্ষক ব্যবস্থাপনা</h1><p className="lede">মোট {data.teachers.length} জন শিক্ষক · ছবি দিলে ল্যান্ডিং পেজের স্লাইডারে দেখা যাবে</p>
          <div className="toolbar"><span className="sp"></span><button className="btn btn-brand" onClick={() => setTeacherForm(true)}>+ নতুন শিক্ষক</button></div>
          {data.teachers.length === 0
            ? <div className="card empty"><b>কোনো শিক্ষক নেই</b>“নতুন শিক্ষক” বোতামে যোগ করুন।</div>
            : <div className="grid3">{data.teachers.map(t => (
              <div className="card" key={t.id} style={{ textAlign: "center" }}>
                {t.photo ? <img src={t.photo} alt={t.name} style={{ width: 84, height: 84, borderRadius: "50%", objectFit: "cover", margin: "0 auto 8px" }} /> : <div className="t-avatar">{t.name.trim().charAt(0)}</div>}
                <h3 style={{ margin: "4px 0 2px" }}>{t.name}</h3>
                <p style={{ margin: 0, color: "var(--muted)", fontSize: "14px" }}>{t.subject} · {t.qualification}<br />{t.phone}</p>
                <button className="mini-btn red" style={{ marginTop: 10 }} onClick={() => patch({ teachers: data.teachers.filter(x => x.id !== t.id) })}>মুছুন</button>
              </div>))}</div>}
        </div>}

        {mod === "classes" && <div>
          <h1>শ্রেণি ও বিষয়</h1><p className="lede">শ্রেণি {data.classes.length}টি · বিষয় {data.subjects.length}টি</p>
          <div className="toolbar"><span className="sp"></span>
            <button className="btn btn-ghost" onClick={() => setSubjectForm(true)}>+ বিষয় যোগ</button>
            <button className="btn btn-brand" onClick={() => setClassForm(true)}>+ শ্রেণি যোগ</button></div>
          <div className="grid2">
            <div className="card"><h3 style={{ marginTop: 0 }}>শ্রেণিসমূহ</h3>
              {data.classes.length === 0 && <p style={{ color: "var(--muted)" }}>কোনো শ্রেণি নেই।</p>}
              {data.classes.map(c => <div className="notice-item" key={c.id}><div><h3>{c.name} শ্রেণি</h3><p>শাখা: {c.sections || "—"} · কক্ষ: {c.room || "—"} · আসন: {c.capacity || "—"} · শিক্ষার্থী: {data.students.filter(x => x.cls === c.name).length} জন</p></div>
                <span style={{ marginLeft: "auto" }}><button className="mini-btn red" onClick={() => patch({ classes: data.classes.filter(x => x.id !== c.id) })}>মুছুন</button></span></div>)}
            </div>
            <div className="card"><h3 style={{ marginTop: 0 }}>বিষয়সমূহ</h3>
              {data.subjects.length === 0 && <p style={{ color: "var(--muted)" }}>কোনো বিষয় নেই।</p>}
              {data.subjects.map(sb => <div className="notice-item" key={sb.id}><div><h3>{sb.name}</h3><p>কোড: {sb.code || "—"} · শ্রেণি: {sb.classes || "সব"}</p></div>
                <span style={{ marginLeft: "auto" }}><button className="mini-btn red" onClick={() => patch({ subjects: data.subjects.filter(x => x.id !== sb.id) })}>মুছুন</button></span></div>)}
            </div>
          </div>
        </div>}

        {mod === "attendance" && <div>
          <h1>দৈনিক হাজিরা</h1><p className="lede">শ্রেণি ও তারিখ বেছে শিক্ষার্থীদের উপস্থিত/অনুপস্থিত চিহ্নিত করুন</p>
          <div className="toolbar">
            <select style={{ maxWidth: 170 }} value={attClass} onChange={e => setAttClass(e.target.value)}>{CLASS_NAMES.map(c => <option key={c}>{c}</option>)}</select>
            <input type="date" style={{ maxWidth: 200 }} value={attDate} onChange={e => setAttDate(e.target.value)} />
            <span className="sp"></span>
            <button className="btn btn-brand" onClick={saveAtt} disabled={attStudents.length === 0}>হাজিরা সংরক্ষণ করুন</button>
          </div>
          {attStudents.length === 0
            ? <div className="card empty"><b>এই শ্রেণিতে শিক্ষার্থী নেই</b>আগে শিক্ষার্থী মডিউল থেকে এই শ্রেণির শিক্ষার্থী যোগ করুন।</div>
            : <div className="table-wrap"><table><thead><tr><th>রোল</th><th>নাম</th><th>অবস্থা</th></tr></thead><tbody>
              {attStudents.slice().sort((a, b) => a.roll - b.roll).map(x => { const v = attMap[x.id] || "P"; return (
                <tr key={x.id}><td>{x.roll}</td><td><b>{x.name}</b></td>
                <td><button className={"att-toggle " + (v === "P" ? "p" : "a")} onClick={() => toggleAtt(x.id)}>{v === "P" ? "✓ উপস্থিত" : "✗ অনুপস্থিত"}</button></td></tr>); })}
              </tbody></table></div>}
          <div className="card" style={{ marginTop: 16 }}><h3 style={{ marginTop: 0 }}>হাজিরার ইতিহাস</h3>
            {attHistory.length === 0 && <p style={{ color: "var(--muted)", margin: 0 }}>এখনো কোনো হাজিরা সংরক্ষণ হয়নি।</p>}
            {attHistory.map(k => { const [dt, cl] = k.split("|"); const m = data.attendance[k]; const p = Object.values(m).filter(v => v === "P").length;
              return <div className="notice-item" key={k}><div><h3>{cl} শ্রেণি — {bnDate(dt)}</h3><p>উপস্থিত {p} জন · অনুপস্থিত {Object.keys(m).length - p} জন</p></div></div>; })}
          </div>
        </div>}

        {mod === "results" && <div>
          <h1>পরীক্ষা ও ফলাফল</h1><p className="lede">বিষয়ভিত্তিক নম্বর দিলে বাংলাদেশি পদ্ধতিতে GPA/গ্রেড অটো হিসাব হবে</p>
          <div className="grid2">
            <div className="card">
              <h3 style={{ marginTop: 0 }}>নম্বর এন্ট্রি</h3>
              <label>শিক্ষার্থী নির্বাচন করুন</label>
              <select value={resStudent} onChange={e => openMarks(e.target.value)}>
                <option value="">— নির্বাচন করুন —</option>
                {data.students.map(x => <option key={x.id} value={x.id}>{x.name} ({x.cls}, রোল {x.roll})</option>)}
              </select>
              {resStudent && <div style={{ marginTop: 12 }}>
                {SUBJECTS.map(sub => <div key={sub} style={{ marginBottom: 9 }}>
                  <label>{sub} (০–১০০)</label>
                  <input type="number" min="0" max="100" value={marks[sub] === undefined ? "" : marks[sub]}
                    onChange={e => setMarks({ ...marks, [sub]: e.target.value })} placeholder="নম্বর" />
                </div>)}
                <button className="btn btn-brand btn-block" onClick={saveMarks}>নম্বর সংরক্ষণ করুন</button>
              </div>}
              {!resStudent && <p style={{ color: "var(--muted)" }}>শিক্ষার্থী বাছলে নম্বর দেওয়ার ঘর আসবে।</p>}
            </div>
            <div className="card">
              <h3 style={{ marginTop: 0 }}>ফলাফল তালিকা</h3>
              {data.students.filter(x => resOf(x.id)).length === 0 && <p style={{ color: "var(--muted)" }}>এখনো কারো ফলাফল দেওয়া হয়নি।</p>}
              {data.students.filter(x => resOf(x.id)).map(x => { const g = gpaOf(x.id); return (
                <div className="notice-item" key={x.id}><div><h3>{x.name} — {x.cls}, রোল {x.roll}</h3>
                  <p>GPA: <b>{g ? g.gpa.toFixed(2) : "—"}</b></p></div>
                  <span style={{ marginLeft: "auto" }}><button className="mini-btn" onClick={() => downloadResult(x)}>ফলাফল শিট ডাউনলোড</button></span></div>); })}
            </div>
          </div>
        </div>}

        {mod === "fees" && <div>
          <h1>ফি ও বকেয়া</h1><p className="lede">আদায় {taka(collected)} · মোট বকেয়া {taka(dues)}</p>
          <div className="note-box">প্রতিটি শিক্ষার্থীর মোট ফি তার <b>বার্ষিক খরচের তালিকা</b> থেকে আসে — ভর্তি ফি, ইউনিফর্ম, টিউশন, স্টেশনারি, পরীক্ষা, ক্রীড়া, উৎসব, পরিবহন, লাইব্রেরি, ল্যাব, উন্নয়ন ও কাস্টম খরচ। খাতভিত্তিক বিস্তারিত ও জমা নিতে অফিস ম্যানেজমেন্টের হিসাব তালিকা ব্যবহার করুন। <button className="mini-btn" onClick={() => setMod("student-costs")}>বার্ষিক খরচের হিসাব খুলুন</button></div>
          {data.students.length === 0
            ? <div className="card empty"><b>শিক্ষার্থী নেই</b>শিক্ষার্থী যোগ হলে এখানে ফি-র হিসাব দেখা যাবে।</div>
            : <div className="table-wrap"><table><thead><tr><th>নাম</th><th>শ্রেণি</th><th>মোট ফি</th><th>জমা</th><th>বকেয়া</th><th>অ্যাকশন</th></tr></thead><tbody>
              {data.students.map(x => { const due = (+x.payable || 0) - (+x.paid || 0); return (
                <tr key={x.id}><td><b>{x.name}</b></td><td>{x.cls}</td><td>{taka(x.payable)}</td><td>{taka(x.paid)}</td>
                <td>{due > 0 ? <span className="pill pill-warn">{taka(due)}</span> : <span className="pill pill-ok">পরিশোধিত</span>}</td>
                <td><button className="mini-btn" onClick={() => { setPayFor(x); setPayAmt(""); }}>ফি জমা নিন</button></td></tr>); })}
              </tbody></table></div>}
        </div>}

        {mod === "notices" && <div>
          <h1>নোটিশ বোর্ড</h1><p className="lede">নোটিশ {data.notices.length}টি · ল্যান্ডিং পেজেও দেখা যায়</p>
          <div className="toolbar"><span className="sp"></span><button className="btn btn-brand" onClick={() => setNoticeForm(true)}>+ নতুন নোটিশ</button></div>
          <div className="card">
            {data.notices.length === 0 && <div className="empty"><b>কোনো নোটিশ নেই</b></div>}
            {data.notices.map(n => <div className="notice-item" key={n.id}>
              <div className="notice-date">{new Date(n.date + "T00:00:00").getDate()}<small>{new Date(n.date + "T00:00:00").toLocaleDateString("bn-BD", { month: "short" })}</small></div>
              <div><h3>{n.title}</h3><p>{n.body}</p></div>
              <span style={{ marginLeft: "auto" }}><button className="mini-btn red" onClick={() => patch({ notices: data.notices.filter(x => x.id !== n.id) })}>মুছুন</button></span></div>)}
          </div>
        </div>}

        {mod === "routine" && <div>
          <h1>ক্লাস রুটিন</h1><p className="lede">সাপ্তাহিক রুটিন (নমুনা কাঠামো — বিষয় অনুযায়ী সাজানো)</p>
          <div className="table-wrap"><table>
            <thead><tr><th>দিন</th><th>১ম পিরিয়ড<br />৯:০০–৯:৫০</th><th>২য় পিরিয়ড<br />৯:৫০–১০:৪০</th><th>৩য় পিরিয়ড<br />১০:৫৫–১১:৪৫</th><th>৪র্থ পিরিয়ড<br />১১:৪৫–১২:৩৫</th><th>৫ম পিরিয়ড<br />১:৩০–২:২০</th></tr></thead>
            <tbody>
              {[["রবিবার", 0], ["সোমবার", 1], ["মঙ্গলবার", 2], ["বুধবার", 3], ["বৃহস্পতিবার", 4]].map(([day, off]) => (
                <tr key={day}><td><b>{day}</b></td>{[0, 1, 2, 3, 4].map(i => <td key={i}>{SUBJECTS[(i + off) % SUBJECTS.length]}</td>)}</tr>
              ))}
            </tbody></table></div>
          <div className="note-box">এই রুটিনটি বিষয় তালিকা থেকে সাজানো একটি কাঠামো। শ্রেণিভেদে আলাদা রুটিন লাগলে শিক্ষক/শ্রেণি অনুযায়ী এন্ট্রি যোগ করা যাবে।</div>
        </div>}

        {mod === "library" && <div>
          <h1>লাইব্রেরি</h1><p className="lede">বই {data.books.length} শিরোনাম · ধার দেওয়া আছে {issuedLoans.length}টি</p>
          <div className="toolbar"><span className="sp"></span>
            <button className="btn btn-ghost" onClick={() => setLoanForm(true)}>বই ধার দিন</button>
            <button className="btn btn-brand" onClick={() => setBookForm(true)}>+ নতুন বই</button></div>
          <div className="grid2">
            <div className="card"><h3 style={{ marginTop: 0 }}>বইয়ের তালিকা</h3>
              {data.books.length === 0 && <p style={{ color: "var(--muted)" }}>কোনো বই নেই।</p>}
              {data.books.map(b => { const out = data.loans.filter(l => l.bookId === b.id && !l.returned).length; return (
                <div className="notice-item" key={b.id}><div><h3>{b.title}</h3><p>লেখক: {b.author} · কপি: {b.copies} · ধারে: {out}টি</p></div>
                <span style={{ marginLeft: "auto" }}><button className="mini-btn red" onClick={() => patch({ books: data.books.filter(x => x.id !== b.id) })}>মুছুন</button></span></div>); })}
            </div>
            <div className="card"><h3 style={{ marginTop: 0 }}>ধার দেওয়া বই</h3>
              {issuedLoans.length === 0 && <p style={{ color: "var(--muted)" }}>এখন কোনো বই ধারে নেই।</p>}
              {issuedLoans.map(l => { const b = data.books.find(x => x.id === l.bookId); const st = data.students.find(x => x.id === l.studentId); return (
                <div className="notice-item" key={l.id}><div><h3>{b ? b.title : "বই"}</h3><p>শিক্ষার্থী: {st ? st.name : "—"} · তারিখ: {bnDate(l.date)}</p></div>
                <span style={{ marginLeft: "auto" }}><button className="mini-btn" onClick={() => patch({ loans: data.loans.map(x => x.id === l.id ? { ...x, returned: true } : x) })}>ফেরত নিন</button></span></div>); })}
            </div>
          </div>
        </div>}

        {mod === "transport" && <div>
          <h1>পরিবহন</h1><p className="lede">রুট {data.routes.length}টি</p>
          <div className="toolbar"><span className="sp"></span><button className="btn btn-brand" onClick={() => setRouteForm(true)}>+ নতুন রুট</button></div>
          {data.routes.length === 0
            ? <div className="card empty"><b>কোনো রুট নেই</b>“নতুন রুট” বোতামে যোগ করুন।</div>
            : <div className="grid3">{data.routes.map(r => (
              <div className="card" key={r.id}><h3 style={{ margin: "0 0 4px" }}>🚌 {r.name}</h3>
                <p style={{ margin: 0, color: "var(--ink2)", fontSize: "14.5px" }}>যান: {r.vehicle}<br />চালক: {r.driver}<br />স্টপেজ: {r.stops}</p>
                <button className="mini-btn red" style={{ marginTop: 10 }} onClick={() => patch({ routes: data.routes.filter(x => x.id !== r.id) })}>মুছুন</button></div>))}
              </div>}
        </div>}

        {mod === "admissions" && <div>
          <h1>ভর্তি আবেদন</h1><p className="lede">মোট {data.admissions.length}টি আবেদন · অপেক্ষমাণ {pendingAdm.length}টি · অনুমোদন দিলে শিক্ষার্থী তালিকায় নাম যুক্ত হবে</p>
          {showCostAtAdmission && <div className="note-box">ভর্তির সময় মোট বার্ষিক খরচ দেখানো <b>চালু</b> আছে — অনুমোদন দিলে শিক্ষার্থীর হিসাবে মোট <b>{taka(yearlyPerStudent)}</b> বার্ষিক খরচের তালিকা তৈরি হবে, যা অফিসের হিসাব তালিকায় দেখা যাবে। এই প্রদর্শন সেটিংস থেকে বন্ধ/চালু করা যায়।</div>}
          {data.admissions.length === 0
            ? <div className="card empty"><b>কোনো আবেদন নেই</b>ল্যান্ডিং পেজের “অনলাইন ভর্তি” থেকে আবেদন এলে এখানে দেখা যাবে।</div>
            : <div className="table-wrap"><table><thead><tr><th>নাম</th><th>শ্রেণি</th><th>অভিভাবক</th><th>মোবাইল</th><th>অবস্থা</th><th>অ্যাকশন</th></tr></thead><tbody>
              {data.admissions.map(a => (
                <tr key={a.id}><td><b>{a.name}</b></td><td>{a.cls}</td><td>{a.guardian || "—"}</td><td>{a.phone || "—"}</td>
                <td>{a.status === "pending" ? <span className="pill pill-warn">অপেক্ষমাণ</span> : a.status === "approved" ? <span className="pill pill-ok">অনুমোদিত</span> : <span className="pill pill-bad">বাতিল</span>}</td>
                <td>{a.status === "pending" && <div className="row-actions">
                  <button className="mini-btn" onClick={() => {
                    const nid = uid(); const items = makeStudentCosts(nid, costTypes, 0); const tot = costTotalsOf(items);
                    patch({ admissions: data.admissions.map(x => x.id === a.id ? { ...x, status: "approved" } : x),
                            students: [...data.students, { id: nid, name: a.name, cls: a.cls, roll: data.students.filter(s2 => s2.cls === a.cls).length + 1, section: "ক", guardian: a.guardian || "", phone: a.phone || "", payable: tot.total, paid: 0 }],
                            studentCosts: [...(data.studentCosts || []), ...items] });
                    toast(a.name + " ভর্তি অনুমোদিত — শিক্ষার্থী তালিকা ও বার্ষিক খরচের হিসাবে যোগ হয়েছে");
                  }}>অনুমোদন</button>
                  <button className="mini-btn red" onClick={() => patch({ admissions: data.admissions.map(x => x.id === a.id ? { ...x, status: "rejected" } : x) })}>বাতিল</button>
                </div>}</td></tr>))}
              </tbody></table></div>}
        </div>}

        {mod === "employees" && <div>
          <h1>অফিস কর্মী ব্যবস্থাপনা</h1><p className="lede">মোট {data.employees.length} জন অফিস কর্মী · শিক্ষক তালিকা থেকে আলাদা অফিস স্টাফ ডেটাবেস</p>
          <div className="toolbar">
            <input type="search" placeholder="নাম বা বিভাগ খুঁজুন…" value={search} onChange={e => setSearch(e.target.value)} />
            <span className="sp"></span>
            <button className="btn btn-brand" onClick={() => { setEditEmp(null); setEmpForm(true); }}>+ নতুন কর্মী</button>
          </div>
          {data.employees.length === 0
            ? <div className="card empty"><b>কোনো অফিস কর্মী নেই</b>“নতুন কর্মী” বোতামে অফিস স্টাফ যোগ করুন। বিভাগ মডিউল থেকে আগে বিভাগ বানালে কর্মী যোগের সময় বিভাগ বাছা যাবে।</div>
            : <div className="table-wrap"><table><thead><tr><th>নাম</th><th>বিভাগ</th><th>পদবি</th><th>মোবাইল</th><th>মাসিক বেতন</th><th>অবস্থা</th><th>অ্যাকশন</th></tr></thead>
              <tbody>{empList.map(x => (
                <tr key={x.id}><td><b>{x.name}</b></td><td>{x.dept || "—"}</td><td>{x.designation || "—"}</td><td>{x.phone || "—"}</td><td>{taka(x.salary)}</td>
                <td>{x.status === "ছুটিতে" ? <span className="pill pill-warn">ছুটিতে</span> : <span className="pill pill-ok">{x.status || "সক্রিয়"}</span>}</td>
                <td><div className="row-actions">
                  <button className="mini-btn" onClick={() => { setEditEmp(x); setEmpForm(true); }}>সম্পাদনা</button>
                  <button className="mini-btn red" onClick={() => patch({ employees: data.employees.filter(e2 => e2.id !== x.id) })}>মুছুন</button>
                </div></td></tr>))}
              </tbody></table></div>}
        </div>}

        {mod === "departments" && <div>
          <h1>বিভাগসমূহ (অফিস)</h1><p className="lede">বিভাগ {data.departments.length}টি · মোট অফিস কর্মী {data.employees.length} জন</p>
          <div className="toolbar"><span className="sp"></span><button className="btn btn-brand" onClick={() => setDeptForm(true)}>+ নতুন বিভাগ</button></div>
          {data.departments.length === 0
            ? <div className="card empty"><b>কোনো বিভাগ নেই</b>“নতুন বিভাগ” বোতামে প্রশাসন, হিসাব, আইটির মতো বিভাগ যোগ করুন।</div>
            : <div className="grid3">{data.departments.map(dp => (
              <div className="card" key={dp.id}><h3 style={{ margin: "0 0 4px" }}>🏢 {dp.name}</h3>
                <p style={{ margin: 0, color: "var(--ink2)", fontSize: "14.5px" }}>বিভাগ প্রধান: {dp.head || "—"}<br />কর্মী: {data.employees.filter(e => e.dept === dp.name).length} জন{dp.note ? <br /> : null}{dp.note || ""}</p>
                <button className="mini-btn red" style={{ marginTop: 10 }} onClick={() => patch({ departments: data.departments.filter(x => x.id !== dp.id) })}>মুছুন</button></div>))}
              </div>}
        </div>}

        {mod === "office-attendance" && <div>
          <h1>অফিস হাজিরা</h1><p className="lede">তারিখ বেছে অফিস কর্মীদের উপস্থিত/অনুপস্থিত চিহ্নিত করুন</p>
          <div className="toolbar">
            <input type="date" style={{ maxWidth: 200 }} value={oAttDate} onChange={e => setOAttDate(e.target.value)} />
            <span className="sp"></span>
            <button className="btn btn-brand" onClick={saveOAtt} disabled={data.employees.length === 0}>হাজিরা সংরক্ষণ করুন</button>
          </div>
          {data.employees.length === 0
            ? <div className="card empty"><b>কোনো অফিস কর্মী নেই</b>আগে অফিস কর্মী মডিউল থেকে কর্মী যোগ করুন।</div>
            : <div className="table-wrap"><table><thead><tr><th>নাম</th><th>বিভাগ</th><th>অবস্থা</th></tr></thead><tbody>
              {data.employees.map(x => { const v = oAttMap[x.id] || "P"; return (
                <tr key={x.id}><td><b>{x.name}</b></td><td>{x.dept || "—"}</td>
                <td><button className={"att-toggle " + (v === "P" ? "p" : "a")} onClick={() => toggleOAtt(x.id)}>{v === "P" ? "✓ উপস্থিত" : "✗ অনুপস্থিত"}</button></td></tr>); })}
              </tbody></table></div>}
          <div className="card" style={{ marginTop: 16 }}><h3 style={{ marginTop: 0 }}>অফিস হাজিরার ইতিহাস</h3>
            {Object.keys(data.officeAttendance).length === 0 && <p style={{ color: "var(--muted)", margin: 0 }}>এখনো কোনো অফিস হাজিরা সংরক্ষণ হয়নি।</p>}
            {Object.keys(data.officeAttendance).sort().reverse().map(dt => { const m = data.officeAttendance[dt]; const pc = Object.values(m).filter(v => v === "P").length;
              return <div className="notice-item" key={dt}><div><h3>{bnDate(dt)}</h3><p>উপস্থিত {pc} জন · অনুপস্থিত {Object.keys(m).length - pc} জন</p></div></div>; })}
          </div>
        </div>}

        {mod === "leaves" && <div>
          <h1>ছুটি ব্যবস্থাপনা</h1><p className="lede">মোট আবেদন {data.leaves.length}টি · অপেক্ষমাণ {pendingLeaves.length}টি</p>
          <div className="toolbar"><span className="sp"></span><button className="btn btn-brand" onClick={() => setLeaveForm(true)}>+ ছুটির আবেদন</button></div>
          {data.leaves.length === 0
            ? <div className="card empty"><b>কোনো ছুটির আবেদন নেই</b>কর্মীর ছুটির আবেদন যোগ করলে এখানে অনুমোদন বা বাতিল করা যাবে।</div>
            : <div className="table-wrap"><table><thead><tr><th>কর্মী</th><th>ছুটির ধরন</th><th>সময়কাল</th><th>কারণ</th><th>অবস্থা</th><th>অ্যাকশন</th></tr></thead><tbody>
              {data.leaves.map(l => (
                <tr key={l.id}><td><b>{empName(l.empId)}</b></td><td>{l.type}</td><td>{bnDate(l.from)} — {bnDate(l.to)}</td><td>{l.reason || "—"}</td>
                <td>{l.status === "pending" ? <span className="pill pill-warn">অপেক্ষমাণ</span> : l.status === "approved" ? <span className="pill pill-ok">অনুমোদিত</span> : <span className="pill pill-bad">বাতিল</span>}</td>
                <td>{l.status === "pending"
                  ? <div className="row-actions">
                      <button className="mini-btn" onClick={() => { patch({ leaves: data.leaves.map(x => x.id === l.id ? { ...x, status: "approved" } : x) }); toast("ছুটি অনুমোদিত হয়েছে"); }}>অনুমোদন</button>
                      <button className="mini-btn red" onClick={() => patch({ leaves: data.leaves.map(x => x.id === l.id ? { ...x, status: "rejected" } : x) })}>বাতিল</button>
                    </div>
                  : <button className="mini-btn red" onClick={() => patch({ leaves: data.leaves.filter(x => x.id !== l.id) })}>মুছুন</button>}</td></tr>))}
              </tbody></table></div>}
        </div>}

        {mod === "payroll" && <div>
          <h1>বেতন / পেরোল</h1><p className="lede">মাস বেছে অফিস কর্মীদের বেতনের হিসাব দেখুন ও এন্ট্রি যোগ করুন</p>
          <div className="toolbar">
            <input type="month" style={{ maxWidth: 200 }} value={payMonth} onChange={e => setPayMonth(e.target.value)} />
            <span style={{ fontWeight: 700 }}>এই মাসের মোট নিট বেতন: {taka(monthPayTotal)}</span>
            <span className="sp"></span>
            <button className="btn btn-brand" onClick={() => setPayrollForm(true)}>+ বেতন এন্ট্রি</button>
          </div>
          {monthPayroll.length === 0
            ? <div className="card empty"><b>এই মাসে বেতন এন্ট্রি নেই</b>“বেতন এন্ট্রি” বোতামে কর্মীর মূল বেতন, ভাতা ও কর্তন যোগ করুন — নিট বেতন অটো হিসাব হবে।</div>
            : <div className="table-wrap"><table><thead><tr><th>কর্মী</th><th>মূল বেতন</th><th>ভাতা</th><th>কর্তন</th><th>নিট বেতন</th><th>অ্যাকশন</th></tr></thead><tbody>
              {monthPayroll.map(x2 => (
                <tr key={x2.id}><td><b>{empName(x2.empId)}</b></td><td>{taka(x2.basic)}</td><td>{taka(x2.allowance)}</td><td>{taka(x2.deduction)}</td>
                <td><b>{taka((+x2.basic || 0) + (+x2.allowance || 0) - (+x2.deduction || 0))}</b></td>
                <td><button className="mini-btn red" onClick={() => patch({ payroll: data.payroll.filter(y => y.id !== x2.id) })}>মুছুন</button></td></tr>))}
              </tbody></table></div>}
        </div>}

        {mod === "tasks" && <div>
          <h1>অফিসের কাজ (টাস্ক)</h1><p className="lede">মোট কাজ {data.tasks.length}টি · চলমান {data.tasks.filter(t => t.status !== "সম্পন্ন").length}টি · সম্পন্ন {data.tasks.filter(t => t.status === "সম্পন্ন").length}টি</p>
          <div className="toolbar"><span className="sp"></span><button className="btn btn-brand" onClick={() => setTaskForm(true)}>+ নতুন কাজ</button></div>
          {data.tasks.length === 0
            ? <div className="card empty"><b>কোনো কাজ নেই</b>“নতুন কাজ” বোতামে অফিস কর্মীকে কাজের দায়িত্ব দিন।</div>
            : <div className="card">
              {data.tasks.map(t => (
                <div className="notice-item" key={t.id}>
                  <div><h3 style={t.status === "সম্পন্ন" ? { textDecoration: "line-through" } : undefined}>{t.title}</h3>
                  <p>দায়িত্বে: {empName(t.empId)} · শেষ তারিখ: {t.due ? bnDate(t.due) : "—"} · অগ্রাধিকার: {t.priority || "মাঝারি"} · অবস্থা: {t.status}</p></div>
                  <span style={{ marginLeft: "auto", display: "flex", gap: 6, flexWrap: "wrap" }}>
                    <button className="mini-btn" onClick={() => patch({ tasks: data.tasks.map(x => x.id === t.id ? { ...x, status: x.status === "সম্পন্ন" ? "চলমান" : "সম্পন্ন" } : x) })}>{t.status === "সম্পন্ন" ? "আবার খুলুন" : "✓ সম্পন্ন করুন"}</button>
                    <button className="mini-btn red" onClick={() => patch({ tasks: data.tasks.filter(x => x.id !== t.id) })}>মুছুন</button>
                  </span>
                </div>))}
            </div>}
        </div>}

        {mod === "expenses" && <div>
          <h1>অফিস খরচ</h1><p className="lede">মোট খরচ {taka(officeExpTotal)} · এন্ট্রি {data.expenses.length}টি</p>
          <div className="toolbar"><span className="sp"></span><button className="btn btn-brand" onClick={() => setExpenseForm(true)}>+ খরচ যোগ</button></div>
          {data.expenses.length === 0
            ? <div className="card empty"><b>কোনো খরচের এন্ট্রি নেই</b>বিদ্যুৎ বিল, স্টেশনারি, রক্ষণাবেক্ষণের মতো অফিস খরচ এখানে যোগ করুন।</div>
            : <div className="table-wrap"><table><thead><tr><th>খরচের খাত</th><th>ধরন</th><th>তারিখ</th><th>পরিমাণ</th><th>নোট</th><th>অ্যাকশন</th></tr></thead><tbody>
              {data.expenses.map(x => (
                <tr key={x.id}><td><b>{x.title}</b></td><td>{x.category || "—"}</td><td>{x.date ? bnDate(x.date) : "—"}</td><td>{taka(x.amount)}</td><td>{x.note || "—"}</td>
                <td><button className="mini-btn red" onClick={() => patch({ expenses: data.expenses.filter(e2 => e2.id !== x.id) })}>মুছুন</button></td></tr>))}
              </tbody></table></div>}
        </div>}

        {mod === "student-costs" && <div>
          <h1>শিক্ষার্থীর বার্ষিক খরচ — অফিস হিসাব</h1>
          <p className="lede">ভর্তি থেকে পুরো বছরের সব খরচের তালিকা · এই হিসাব অফিস ম্যানেজমেন্টের হিসাব তালিকায় থাকে · ভর্তির সময় মোট খরচ দেখানো: {showCostAtAdmission ? "চালু" : "বন্ধ"} (সেটিংস থেকে বদলানো যায়)</p>
          <div className="kpis">
            <div className="kpi"><b>{taka(yearly.total)}</b><span>মোট বার্ষিক খরচ (সব শিক্ষার্থী)</span></div>
            <div className="kpi"><b>{taka(yearly.paid)}</b><span>মোট আদায়</span></div>
            <div className="kpi"><b>{taka(yearly.due)}</b><span>মোট বকেয়া</span></div>
            <div className="kpi"><b>{costTypes.length}</b><span>খরচের ধরন</span></div>
          </div>

          <div className="card" style={{ marginBottom: 16 }}>
            <h3 style={{ marginTop: 0 }}>খরচের ধরন — ভর্তি থেকে পুরো বছরের তালিকা</h3>
            <p style={{ color: "var(--ink2)", fontSize: "14.5px" }}>নতুন শিক্ষার্থী যোগ বা ভর্তি অনুমোদন হলেই এই তালিকা অনুযায়ী তার বার্ষিক খরচ তৈরি হয়। নিজের দরকারমতো নতুন (কাস্টম) খরচের ধরন যোগ করুন, পরিমাণ বদলান বা মুছুন। পরিমাণ বদলালে তা নতুন ভর্তির ক্ষেত্রে প্রযোজ্য হবে; আগের শিক্ষার্থীদের তালিকা তাদের বিস্তারিত থেকে বদলাতে পারবেন।</p>
            <div className="toolbar"><span className="sp"></span><button className="btn btn-brand btn-sm" onClick={() => { setEditCostType(null); setCostTypeForm(true); }}>+ কাস্টম খরচের ধরন যোগ</button></div>
            <div className="table-wrap"><table><thead><tr><th>খরচের খাত</th><th>পরিমাণ (বার্ষিক)</th><th>ধরন</th><th>অ্যাকশন</th></tr></thead><tbody>
              {costTypes.map(t => (
                <tr key={t.id}><td><b>{t.name}</b></td><td>{taka(t.amount)}</td>
                <td>{t.isCustom ? <span className="pill pill-info">কাস্টম</span> : <span className="pill pill-ok">নির্ধারিত</span>}</td>
                <td><div className="row-actions">
                  <button className="mini-btn" onClick={() => { setEditCostType(t); setCostTypeForm(true); }}>সম্পাদনা</button>
                  <button className="mini-btn red" onClick={() => delCostType(t)}>মুছুন</button>
                </div></td></tr>))}
              <tr><td><b>মোট (প্রতি শিক্ষার্থী, পুরো বছর)</b></td><td><b>{taka(yearlyPerStudent)}</b></td><td></td><td></td></tr>
            </tbody></table></div>
          </div>

          <div className="card" style={{ marginBottom: 16 }}>
            <h3 style={{ marginTop: 0 }}>শিক্ষার্থী অনুযায়ী হিসাব (অফিস হিসাব তালিকা)</h3>
            {data.students.length === 0
              ? <div className="empty"><b>কোনো শিক্ষার্থী নেই</b>শিক্ষার্থী যোগ বা ভর্তি অনুমোদন হলেই এখানে তার বার্ষিক খরচের হিসাব আসবে।</div>
              : <div className="table-wrap"><table><thead><tr><th>নাম</th><th>শ্রেণি</th><th>রোল</th><th>মোট বার্ষিক খরচ</th><th>জমা</th><th>বকেয়া</th><th>অবস্থা</th><th>অ্যাকশন</th></tr></thead><tbody>
                {data.students.map(x => { const t = costTotalsOf(costsOf(x.id)); return (
                  <tr key={x.id}><td><b>{x.name}</b></td><td>{x.cls}</td><td>{x.roll}</td><td>{taka(t.total)}</td><td>{taka(t.paid)}</td>
                  <td>{t.due > 0 ? taka(t.due) : "—"}</td>
                  <td>{t.due <= 0 ? <span className="pill pill-ok">পরিশোধিত</span> : t.paid > 0 ? <span className="pill pill-info">আংশিক জমা</span> : <span className="pill pill-warn">বকেয়া</span>}</td>
                  <td><button className="mini-btn" onClick={() => setCostStudentId(costStudentId === x.id ? "" : x.id)}>{costStudentId === x.id ? "বন্ধ করুন" : "বিস্তারিত খরচ"}</button></td></tr>); })}
                </tbody></table></div>}
          </div>

          {costStudentId && data.students.find(x => x.id === costStudentId) && (() => { const st = data.students.find(x => x.id === costStudentId); const list = costsOf(st.id); const t = costTotalsOf(list); return (
            <div className="card" style={{ marginBottom: 16 }}>
              <h3 style={{ marginTop: 0 }}>{st.name} — বার্ষিক খরচের বিস্তারিত ({st.cls}, রোল {st.roll})</h3>
              <p style={{ color: "var(--ink2)", fontSize: "14.5px" }}>মোট {taka(t.total)} · জমা {taka(t.paid)} · বকেয়া {taka(t.due)}</p>
              <div className="toolbar">
                <button className="btn btn-ghost btn-sm" onClick={() => setCostItemAdd(st)}>+ এই শিক্ষার্থীর জন্য আলাদা খরচ যোগ</button>
                <button className="btn btn-ghost btn-sm" onClick={() => downloadCostSheet(st)}>খরচের তালিকা ডাউনলোড</button>
                <span className="sp"></span>
                <button className="btn btn-ghost btn-sm" onClick={() => setCostStudentId("")}>বন্ধ করুন</button>
              </div>
              <div className="table-wrap"><table><thead><tr><th>খরচের খাত</th><th>পরিমাণ</th><th>জমা</th><th>বকেয়া</th><th>অবস্থা</th><th>অ্যাকশন</th></tr></thead><tbody>
                {list.map(c => { const due = Math.max(0, (+c.amount || 0) - (+c.paid || 0)); return (
                  <tr key={c.id}><td><b>{c.name}</b></td><td>{taka(c.amount)}</td><td>{taka(c.paid)}</td><td>{due > 0 ? taka(due) : "—"}</td>
                  <td>{due <= 0 ? <span className="pill pill-ok">পরিশোধিত</span> : (+c.paid || 0) > 0 ? <span className="pill pill-info">আংশিক</span> : <span className="pill pill-warn">বকেয়া</span>}</td>
                  <td><div className="row-actions">
                    <button className="mini-btn" onClick={() => { setCostPayFor(c); setCostPayAmt(""); }}>জমা নিন</button>
                    <button className="mini-btn" onClick={() => setCostItemEdit(c)}>সম্পাদনা</button>
                    <button className="mini-btn red" onClick={() => updateStudentCosts(st.id, list.filter(y => y.id !== c.id))}>মুছুন</button>
                  </div></td></tr>); })}
              </tbody></table></div>
            </div>); })()}

          <div className="grid2">
            <div className="card">
              <h3 style={{ marginTop: 0 }}>শ্রেণি অনুযায়ী মোট হিসাব</h3>
              {data.students.length === 0 ? <p style={{ color: "var(--muted)" }}>শিক্ষার্থী নেই।</p>
              : <div className="table-wrap"><table><thead><tr><th>শ্রেণি</th><th>শিক্ষার্থী</th><th>মোট খরচ</th><th>আদায়</th><th>বকেয়া</th></tr></thead><tbody>
                {CLASS_NAMES.map(cl => { const sts = data.students.filter(x => x.cls === cl); if (!sts.length) return null; const tt = sts.reduce((acc, x) => { const q = costTotalsOf(costsOf(x.id)); acc.total += q.total; acc.paid += q.paid; acc.due += q.due; return acc; }, { total: 0, paid: 0, due: 0 }); return (
                  <tr key={cl}><td><b>{cl}</b></td><td>{sts.length} জন</td><td>{taka(tt.total)}</td><td>{taka(tt.paid)}</td><td>{taka(tt.due)}</td></tr>); })}
                </tbody></table></div>}
            </div>
            <div className="card">
              <h3 style={{ marginTop: 0 }}>খাত অনুযায়ী মোট হিসাব</h3>
              {data.students.length === 0 ? <p style={{ color: "var(--muted)" }}>শিক্ষার্থী নেই।</p>
              : <div className="table-wrap"><table><thead><tr><th>খরচের খাত</th><th>মোট</th><th>আদায়</th><th>বকেয়া</th></tr></thead><tbody>
                {(() => { const byName = {}; data.students.forEach(x => costsOf(x.id).forEach(c => { if (!byName[c.name]) byName[c.name] = { total: 0, paid: 0 }; byName[c.name].total += +c.amount || 0; byName[c.name].paid += +c.paid || 0; })); return Object.keys(byName).map(nm => (
                  <tr key={nm}><td><b>{nm}</b></td><td>{taka(byName[nm].total)}</td><td>{taka(byName[nm].paid)}</td><td>{taka(byName[nm].total - byName[nm].paid)}</td></tr>)); })()}
                </tbody></table></div>}
            </div>
          </div>
        </div>}

        {mod === "office-docs" && <div>
          <h1>নথি ও অফিস নোটিশ</h1><p className="lede">মোট {data.officeDocs.length}টি · অফিসের অভ্যন্তরীণ নথি ও নোটিশের রেকর্ড (স্কুলের পাবলিক নোটিশ বোর্ড থেকে আলাদা)</p>
          <div className="toolbar"><span className="sp"></span><button className="btn btn-brand" onClick={() => setDocForm(true)}>+ নথি / নোটিশ যোগ</button></div>
          <div className="card">
            {data.officeDocs.length === 0 && <div className="empty"><b>কোনো নথি নেই</b>অফিস নোটিশ, চুক্তি, চিঠি ইত্যাদির রেকর্ড এখানে রাখুন।</div>}
            {data.officeDocs.map(d => (
              <div className="notice-item" key={d.id}>
                <div className="notice-date">{d.date ? new Date(d.date + "T00:00:00").getDate() : "—"}<small>{d.date ? new Date(d.date + "T00:00:00").toLocaleDateString("bn-BD", { month: "short" }) : ""}</small></div>
                <div><h3>{d.title} <span className="pill pill-info">{d.category || "নথি"}</span></h3><p>{d.note || ""}</p></div>
                <span style={{ marginLeft: "auto" }}><button className="mini-btn red" onClick={() => patch({ officeDocs: data.officeDocs.filter(x => x.id !== d.id) })}>মুছুন</button></span>
              </div>))}
          </div>
        </div>}

        {mod === "settings" && <div>
          <h1>সেটিংস</h1><p className="lede">স্কুলের তথ্য বদলালে ল্যান্ডিং পেজে সঙ্গে সঙ্গে দেখা যাবে</p>
          <SettingsForm data={data} setData={setData} toast={toast} onPhoto={onPhoto} photoErr={photoErr} downloadBackup={downloadBackup} importBackup={importBackup} />
        </div>}

      </main>

      {showStudentForm && <StudentForm initial={editStudent} close={() => { setShowStudentForm(false); setEditStudent(null); }} save={saveStudent} costTypes={costTypes} showCost={showCostAtAdmission} existingCosts={editStudent ? costsOf(editStudent.id) : null} />}
      {teacherForm && <TeacherForm close={() => setTeacherForm(false)} onPhoto={onPhoto} photoErr={photoErr}
        save={f => { patch({ teachers: [...data.teachers, { ...f, id: uid() }] }); setTeacherForm(false); toast("শিক্ষক যোগ হয়েছে"); }} />}
      {classForm && <SimpleForm title="নতুন শ্রেণি" close={() => setClassForm(false)}
        fields={[{ k: "name", l: "শ্রেণির নাম (যেমন: ষষ্ঠ)" }, { k: "sections", l: "শাখা (যেমন: ক, খ)" }, { k: "room", l: "কক্ষ নম্বর" }, { k: "capacity", l: "আসন সংখ্যা", type: "number" }]}
        save={f => { patch({ classes: [...data.classes, { ...f, id: uid() }] }); setClassForm(false); toast("শ্রেণি যোগ হয়েছে"); }} />}
      {subjectForm && <SimpleForm title="নতুন বিষয়" close={() => setSubjectForm(false)}
        fields={[{ k: "name", l: "বিষয়ের নাম" }, { k: "code", l: "বিষয় কোড" }, { k: "classes", l: "যে শ্রেণির জন্য" }]}
        save={f => { patch({ subjects: [...data.subjects, { ...f, id: uid() }] }); setSubjectForm(false); toast("বিষয় যোগ হয়েছে"); }} />}
      {noticeForm && <SimpleForm title="নতুন নোটিশ" close={() => setNoticeForm(false)}
        fields={[{ k: "title", l: "শিরোনাম" }, { k: "date", l: "তারিখ", type: "date", def: todayStr() }, { k: "body", l: "বিবরণ", area: true }]}
        save={f => { patch({ notices: [{ ...f, id: uid() }, ...data.notices] }); setNoticeForm(false); toast("নোটিশ প্রকাশ হয়েছে"); }} />}
      {bookForm && <SimpleForm title="নতুন বই" close={() => setBookForm(false)}
        fields={[{ k: "title", l: "বইয়ের নাম" }, { k: "author", l: "লেখক" }, { k: "copies", l: "কপি সংখ্যা", type: "number", def: "1" }]}
        save={f => { patch({ books: [...data.books, { ...f, id: uid(), copies: +f.copies || 1 }] }); setBookForm(false); toast("বই যোগ হয়েছে"); }} />}
      {routeForm && <SimpleForm title="নতুন রুট" close={() => setRouteForm(false)}
        fields={[{ k: "name", l: "রুটের নাম" }, { k: "vehicle", l: "যান" }, { k: "driver", l: "চালক" }, { k: "stops", l: "স্টপেজসমূহ", area: true }]}
        save={f => { patch({ routes: [...data.routes, { ...f, id: uid() }] }); setRouteForm(false); toast("রুট যোগ হয়েছে"); }} />}
      {loanForm && <LoanForm data={data} close={() => setLoanForm(false)}
        save={(bookId, studentId) => { patch({ loans: [...data.loans, { id: uid(), bookId, studentId, date: todayStr(), returned: false }] }); setLoanForm(false); toast("বই ধার দেওয়া হয়েছে"); }} />}
      {payFor && (
        <div className="modal-bg" onClick={e => { if (e.target === e.currentTarget) setPayFor(null); }}>
          <form className="modal" onSubmit={e => { e.preventDefault(); savePay(); }}>
            <h2>ফি জমা নিন</h2>
            <p className="sub">{payFor.name} · বকেয়া {taka((+payFor.payable || 0) - (+payFor.paid || 0))}</p>
            <label>জমার পরিমাণ (৳)</label>
            <input type="number" min="1" value={payAmt} onChange={e => setPayAmt(e.target.value)} autoFocus />
            <div style={{ display: "flex", gap: 9, marginTop: 16, flexWrap: "wrap" }}>
              <button type="submit" className="btn btn-brand" style={{ flex: 1 }}>জমা নিশ্চিত করুন</button>
              <button type="button" className="btn btn-ghost" onClick={() => setPayFor(null)}>বাতিল</button>
            </div>
          </form>
        </div>
      )}
      {empForm && <SimpleForm title={editEmp ? "কর্মী সম্পাদনা" : "নতুন অফিস কর্মী"} close={() => { setEmpForm(false); setEditEmp(null); }}
        fields={[
          { k: "name", l: "নাম *", def: editEmp ? editEmp.name : "" },
          { k: "dept", l: "বিভাগ", options: Array.from(new Set([...data.departments.map(d => d.name), editEmp ? editEmp.dept : ""].filter(Boolean))), def: editEmp ? editEmp.dept : "" },
          { k: "designation", l: "পদবি", def: editEmp ? editEmp.designation : "" },
          { k: "phone", l: "মোবাইল", def: editEmp ? editEmp.phone : "" },
          { k: "email", l: "ইমেইল", def: editEmp ? editEmp.email : "" },
          { k: "salary", l: "মাসিক বেতন (৳)", type: "number", def: editEmp ? String(editEmp.salary || "") : "" },
          { k: "joinDate", l: "যোগদানের তারিখ", type: "date", def: editEmp ? editEmp.joinDate : "" },
          { k: "status", l: "অবস্থা", options: ["সক্রিয়", "ছুটিতে", "অবসরপ্রাপ্ত"], def: editEmp ? editEmp.status : "সক্রিয়" }
        ]}
        save={f => { if (f.name && f.name.trim()) saveEmp(f); }} />}
      {deptForm && <SimpleForm title="নতুন বিভাগ" close={() => setDeptForm(false)}
        fields={[{ k: "name", l: "বিভাগের নাম (যেমন: প্রশাসন)" }, { k: "head", l: "বিভাগ প্রধান" }, { k: "note", l: "নোট", area: true }]}
        save={f => { if (!f.name.trim()) return; patch({ departments: [...data.departments, { ...f, id: uid() }] }); setDeptForm(false); toast("বিভাগ যোগ হয়েছে"); }} />}
      {leaveForm && <SimpleForm title="ছুটির আবেদন" close={() => setLeaveForm(false)}
        fields={[
          { k: "empId", l: "কর্মী", options: data.employees.map(e => ({ v: e.id, l: e.name + (e.dept ? " (" + e.dept + ")" : "") })) },
          { k: "type", l: "ছুটির ধরন", options: ["নৈমিত্তিক", "অসুস্থতা", "বার্ষিক", "মাতৃত্ব", "বিনা বেতনে", "অন্যান্য"], def: "নৈমিত্তিক" },
          { k: "from", l: "শুরুর তারিখ", type: "date", def: todayStr() },
          { k: "to", l: "শেষ তারিখ", type: "date", def: todayStr() },
          { k: "reason", l: "কারণ", area: true }
        ]}
        save={f => { if (!f.empId) { toast("আগে কর্মী বাছুন", true); return; } patch({ leaves: [{ ...f, id: uid(), status: "pending" }, ...data.leaves] }); setLeaveForm(false); toast("ছুটির আবেদন জমা হয়েছে"); }} />}
      {payrollForm && <SimpleForm title="বেতন এন্ট্রি" close={() => setPayrollForm(false)}
        fields={[
          { k: "empId", l: "কর্মী", options: data.employees.map(e => ({ v: e.id, l: e.name })) },
          { k: "month", l: "মাস", type: "month", def: payMonth },
          { k: "basic", l: "মূল বেতন (৳) — খালি রাখলে কর্মীর নির্ধারিত বেতন বসবে", type: "number" },
          { k: "allowance", l: "ভাতা (৳)", type: "number", def: "0" },
          { k: "deduction", l: "কর্তন (৳)", type: "number", def: "0" }
        ]}
        save={f => { if (!f.empId) { toast("আগে কর্মী বাছুন", true); return; } const emp = data.employees.find(e => e.id === f.empId); patch({ payroll: [...data.payroll, { id: uid(), empId: f.empId, month: f.month || payMonth, basic: f.basic === "" || f.basic === undefined ? (emp ? +emp.salary || 0 : 0) : (+f.basic || 0), allowance: +f.allowance || 0, deduction: +f.deduction || 0 }] }); setPayrollForm(false); toast("বেতন এন্ট্রি যোগ হয়েছে"); }} />}
      {taskForm && <SimpleForm title="নতুন অফিসের কাজ" close={() => setTaskForm(false)}
        fields={[
          { k: "title", l: "কাজের বিবরণ" },
          { k: "empId", l: "দায়িত্বে (কর্মী)", options: data.employees.map(e => ({ v: e.id, l: e.name })) },
          { k: "due", l: "শেষ তারিখ", type: "date", def: todayStr() },
          { k: "priority", l: "অগ্রাধিকার", options: ["উচ্চ", "মাঝারি", "কম"], def: "মাঝারি" }
        ]}
        save={f => { if (!f.title.trim()) return; patch({ tasks: [{ ...f, id: uid(), status: "চলমান" }, ...data.tasks] }); setTaskForm(false); toast("কাজ যোগ হয়েছে"); }} />}
      {expenseForm && <SimpleForm title="অফিস খরচ যোগ" close={() => setExpenseForm(false)}
        fields={[
          { k: "title", l: "খরচের খাত (যেমন: বিদ্যুৎ বিল)" },
          { k: "category", l: "ধরন", options: ["ইউটিলিটি", "স্টেশনারি", "রক্ষণাবেক্ষণ", "পরিবহন", "খাবার ও আপ্যায়ন", "অন্যান্য"], def: "অন্যান্য" },
          { k: "amount", l: "পরিমাণ (৳)", type: "number" },
          { k: "date", l: "তারিখ", type: "date", def: todayStr() },
          { k: "note", l: "নোট", area: true }
        ]}
        save={f => { if (!f.title.trim()) return; patch({ expenses: [{ ...f, id: uid(), amount: +f.amount || 0 }, ...data.expenses] }); setExpenseForm(false); toast("খরচ যোগ হয়েছে"); }} />}
      {docForm && <SimpleForm title="নথি / অফিস নোটিশ যোগ" close={() => setDocForm(false)}
        fields={[
          { k: "title", l: "শিরোনাম" },
          { k: "category", l: "ধরন", options: ["নোটিশ", "চুক্তি", "চিঠি", "রসিদ", "সভার কার্যবিবরণী", "অন্যান্য"], def: "নোটিশ" },
          { k: "date", l: "তারিখ", type: "date", def: todayStr() },
          { k: "note", l: "বিবরণ / নোট", area: true }
        ]}
        save={f => { if (!f.title.trim()) return; patch({ officeDocs: [{ ...f, id: uid() }, ...data.officeDocs] }); setDocForm(false); toast("নথি যোগ হয়েছে"); }} />}
      {costTypeForm && <SimpleForm title={editCostType ? "খরচের ধরন সম্পাদনা" : "কাস্টম খরচের ধরন যোগ"} close={() => { setCostTypeForm(false); setEditCostType(null); }}
        fields={[
          { k: "name", l: "খরচের খাত (যেমন: কোচিং ফি, বইয়ের মূল্য, সফর ফি)", def: editCostType ? editCostType.name : "" },
          { k: "amount", l: "বার্ষিক পরিমাণ (৳)", type: "number", def: editCostType ? String(editCostType.amount || "") : "" }
        ]}
        save={saveCostType} />}
      {costItemEdit && <SimpleForm title={"খরচ সম্পাদনা — " + costItemEdit.name} close={() => setCostItemEdit(null)}
        fields={[
          { k: "amount", l: "পরিমাণ (৳)", type: "number", def: String(costItemEdit.amount || "") },
          { k: "paid", l: "জমা (৳)", type: "number", def: String(costItemEdit.paid || "") }
        ]}
        save={f => { const amt = +f.amount || 0; const list = costsOf(costItemEdit.studentId).map(c => c.id === costItemEdit.id ? { ...c, amount: amt, paid: Math.min(amt, +f.paid || 0) } : c); updateStudentCosts(costItemEdit.studentId, list); setCostItemEdit(null); toast("খরচ আপডেট হয়েছে"); }} />}
      {costItemAdd && <SimpleForm title={"আলাদা খরচ যোগ — " + costItemAdd.name} close={() => setCostItemAdd(null)}
        fields={[
          { k: "name", l: "খরচের খাত (যেমন: অতিরিক্ত বই, বিশেষ কোচিং)" },
          { k: "amount", l: "পরিমাণ (৳)", type: "number" }
        ]}
        save={f => { if (!f.name.trim()) return; const list = [...costsOf(costItemAdd.id), { id: uid(), studentId: costItemAdd.id, costTypeId: "custom", name: f.name, amount: +f.amount || 0, paid: 0 }]; updateStudentCosts(costItemAdd.id, list); setCostItemAdd(null); toast("শিক্ষার্থীর তালিকায় আলাদা খরচ যোগ হয়েছে"); }} />}
      {costPayFor && (
        <div className="modal-bg" onClick={e => { if (e.target === e.currentTarget) setCostPayFor(null); }}>
          <form className="modal" onSubmit={e => { e.preventDefault(); saveCostPay(); }}>
            <h2>খরচের জমা নিন</h2>
            <p className="sub">{costPayFor.name} · বকেয়া {taka(Math.max(0, (+costPayFor.amount || 0) - (+costPayFor.paid || 0)))}</p>
            <label>জমার পরিমাণ (৳)</label>
            <input type="number" min="1" value={costPayAmt} onChange={e => setCostPayAmt(e.target.value)} autoFocus />
            <div style={{ display: "flex", gap: 9, marginTop: 16, flexWrap: "wrap" }}>
              <button type="submit" className="btn btn-brand" style={{ flex: 1 }}>জমা নিশ্চিত করুন</button>
              <button type="button" className="btn btn-ghost" onClick={() => setCostPayFor(null)}>বাতিল</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

/* ---------- ফর্মসমূহ ---------- */
function StudentForm({ initial, close, save, costTypes, showCost, existingCosts }) {
  const [f, setF] = useState(initial || { name: "", cls: "ষষ্ঠ", roll: "", section: "ক", guardian: "", phone: "", payable: 12000, paid: 0 });
  const set = k => e => setF({ ...f, [k]: e.target.value });
  const previewList = existingCosts && existingCosts.length ? existingCosts : (costTypes || []).map(t => ({ name: t.name, amount: +t.amount || 0, paid: 0 }));
  const previewTotal = previewList.reduce((a, c) => a + (+c.amount || 0), 0);
  return (
    <ModalForm title={initial ? "শিক্ষার্থী সম্পাদনা" : "নতুন শিক্ষার্থী"} close={close} onSubmit={() => { if (f.name.trim()) save({ ...f, roll: +f.roll || 0, payable: showCost ? previewTotal : (+f.payable || 0), paid: +f.paid || 0 }); }}>
      <Field label="নাম *" full><input value={f.name} onChange={set("name")} required /></Field>
      <Field label="শ্রেণি"><select value={f.cls} onChange={set("cls")}>{CLASS_NAMES.map(c => <option key={c}>{c}</option>)}</select></Field>
      <Field label="রোল"><input type="number" value={f.roll} onChange={set("roll")} /></Field>
      <Field label="শাখা"><input value={f.section} onChange={set("section")} /></Field>
      <Field label="অভিভাবকের নাম"><input value={f.guardian} onChange={set("guardian")} /></Field>
      <Field label="মোবাইল"><input value={f.phone} onChange={set("phone")} /></Field>
      {!showCost && <Field label="মোট ফি (৳)"><input type="number" value={f.payable} onChange={set("payable")} /></Field>}
      {showCost && <Field label="বার্ষিক খরচের তালিকা — ভর্তির সময় মোট খরচ" full>
        <div className="note-box" style={{ margin: 0 }}>
          {previewList.map((c, i) => <div key={i} style={{ display: "flex", justifyContent: "space-between", gap: 10 }}><span>{c.name}</span><b>{taka(c.amount)}</b></div>)}
          <div style={{ display: "flex", justifyContent: "space-between", gap: 10, borderTop: "1px solid var(--line)", marginTop: 6, paddingTop: 6 }}><span><b>মোট বার্ষিক খরচ</b></span><b>{taka(previewTotal)}</b></div>
          <div style={{ fontSize: "12.5px", marginTop: 4 }}>এই মোট অঙ্কই শিক্ষার্থীর মোট ফি হিসাবে বসবে এবং অফিসের হিসাব তালিকায় (শিক্ষার্থীর বার্ষিক খরচ) দেখা যাবে।</div>
        </div>
      </Field>}
    </ModalForm>
  );
}
function TeacherForm({ close, save, onPhoto, photoErr }) {
  const [f, setF] = useState({ name: "", subject: "", phone: "", qualification: "", photo: "" });
  const set = k => e => setF({ ...f, [k]: e.target.value });
  return (
    <ModalForm title="নতুন শিক্ষক" close={close} onSubmit={() => { if (f.name.trim()) save(f); }}>
      <Field label="নাম *" full><input value={f.name} onChange={set("name")} required /></Field>
      <Field label="বিষয়"><input value={f.subject} onChange={set("subject")} /></Field>
      <Field label="মোবাইল"><input value={f.phone} onChange={set("phone")} /></Field>
      <Field label="শিক্ষাগত যোগ্যতা" full><input value={f.qualification} onChange={set("qualification")} /></Field>
      <Field label="ছবি (ঐচ্ছিক — ল্যান্ডিং পেজের স্লাইডারে দেখা যাবে)" full>
        <input type="file" accept="image/*" onChange={e => onPhoto(e, url => setF(prev => ({ ...prev, photo: url })))} />
        {photoErr && <span style={{ color: "var(--danger)", fontSize: "13px" }}>{photoErr}</span>}
        {f.photo && <img src={f.photo} alt="শিক্ষকের ছবি" style={{ width: 72, height: 72, borderRadius: "50%", objectFit: "cover", marginTop: 8 }} />}
      </Field>
    </ModalForm>
  );
}
function SimpleForm({ title, fields, close, save }) {
  const init = {}; fields.forEach(fd => { init[fd.k] = fd.def || ""; });
  const [f, setF] = useState(init);
  return (
    <ModalForm title={title} close={close} onSubmit={() => save(f)}>
      {fields.map(fd => (
        <Field key={fd.k} label={fd.l} full={!!fd.area}>
          {fd.area
            ? <textarea rows="3" value={f[fd.k]} onChange={e => setF({ ...f, [fd.k]: e.target.value })} />
            : fd.options
              ? <select value={f[fd.k]} onChange={e => setF({ ...f, [fd.k]: e.target.value })}>
                  <option value="">— বাছুন —</option>
                  {fd.options.map(o => { const ov = typeof o === "object" ? o.v : o; const ol = typeof o === "object" ? o.l : o; return <option key={ov} value={ov}>{ol}</option>; })}
                </select>
              : <input type={fd.type || "text"} value={f[fd.k]} onChange={e => setF({ ...f, [fd.k]: e.target.value })} />}
        </Field>
      ))}
    </ModalForm>
  );
}
function LoanForm({ data, close, save }) {
  const [bookId, setBookId] = useState(""); const [studentId, setStudentId] = useState("");
  return (
    <ModalForm title="বই ধার দিন" close={close} onSubmit={() => { if (bookId && studentId) save(bookId, studentId); }} submitLabel="ধার দিন">
      <Field label="বই" full><select value={bookId} onChange={e => setBookId(e.target.value)}>
        <option value="">— বই বাছুন —</option>{data.books.map(b => <option key={b.id} value={b.id}>{b.title}</option>)}</select></Field>
      <Field label="শিক্ষার্থী" full><select value={studentId} onChange={e => setStudentId(e.target.value)}>
        <option value="">— শিক্ষার্থী বাছুন —</option>{data.students.map(x => <option key={x.id} value={x.id}>{x.name} ({x.cls})</option>)}</select></Field>
    </ModalForm>
  );
}
function SettingsForm({ data, setData, toast, downloadBackup, importBackup }) {
  const s = data.settings;
  const [f, setF] = useState(s);
  const set = k => e => setF({ ...f, [k]: e.target.value });
  return (
    <div>
      <div className="card" style={{ marginBottom: 16 }}>
        <div className="form-grid">
          <Field label="স্কুলের নাম" full><input value={f.name} onChange={set("name")} /></Field>
          <Field label="মূলমন্ত্র"><input value={f.motto} onChange={set("motto")} /></Field>
          <Field label="প্রতিষ্ঠা সাল"><input value={f.established} onChange={set("established")} /></Field>
          <Field label="ঠিকানা" full><input value={f.address} onChange={set("address")} /></Field>
          <Field label="মোবাইল"><input value={f.phone} onChange={set("phone")} /></Field>
          <Field label="ইমেইল"><input value={f.email} onChange={set("email")} /></Field>
          <Field label="প্রধানের নাম"><input value={f.principalName} onChange={set("principalName")} /></Field>
          <Field label="প্রধানের বার্তা" full><textarea rows="3" value={f.principalMsg} onChange={set("principalMsg")} /></Field>
          <Field label="Facebook পেজের লিংক"><input value={f.fb} onChange={set("fb")} placeholder="https://facebook.com/…" /></Field>
          <Field label="YouTube লিংক"><input value={f.yt} onChange={set("yt")} placeholder="https://youtube.com/…" /></Field>
          <Field label="Instagram লিংক"><input value={f.ig} onChange={set("ig")} placeholder="https://instagram.com/…" /></Field>
        </div>
        <button className="btn btn-brand" style={{ marginTop: 14 }} onClick={() => { setData({ ...data, settings: f }); toast("সেটিংস সংরক্ষিত — ল্যান্ডিং পেজে দেখুন"); }}>সেটিংস সংরক্ষণ করুন</button>
      </div>
      <div className="card" style={{ marginBottom: 16 }}>
        <h3 style={{ marginTop: 0 }}>শিক্ষার্থীর বার্ষিক খরচ — প্রদর্শন সেটিংস</h3>
        <p style={{ color: "var(--ink2)", fontSize: "14.5px" }}>ভর্তির সময় (অনলাইন ভর্তি ফরম, কনসোলের নতুন শিক্ষার্থী ফরম ও ভর্তি অনুমোদনে) মোট বার্ষিক খরচ দেখানো এখন <b>{data.settings.showYearlyCostAtAdmission !== false ? "চালু" : "বন্ধ"}</b> আছে। প্রতি শিক্ষার্থীর মোট বার্ষিক খরচ বর্তমানে <b>{taka(costTypesOf(data).reduce((a, t) => a + (+t.amount || 0), 0))}</b> (সব খরচের ধরন মিলিয়ে)। খরচের ধরন যোগ/বদল/মুছতে এবং প্রতিটি শিক্ষার্থীর খাতভিত্তিক হিসাব দেখতে অফিস ম্যানেজমেন্টের “শিক্ষার্থীর বার্ষিক খরচ” মডিউল ব্যবহার করুন — সব শিক্ষার্থীর খরচ সেখানকার হিসাব তালিকায় থাকে।</p>
        <button className="btn btn-brand btn-sm" onClick={() => { const nv = data.settings.showYearlyCostAtAdmission === false; setData({ ...data, settings: { ...data.settings, showYearlyCostAtAdmission: nv } }); setF({ ...f, showYearlyCostAtAdmission: nv }); toast(nv ? "ভর্তির সময় মোট বার্ষিক খরচ দেখানো চালু হয়েছে" : "ভর্তির সময় মোট বার্ষিক খরচ দেখানো বন্ধ হয়েছে"); }}>{data.settings.showYearlyCostAtAdmission !== false ? "ভর্তির সময় মোট খরচ দেখানো বন্ধ করুন" : "ভর্তির সময় মোট খরচ দেখান"}</button>
      </div>
      <div className="card" style={{ marginBottom: 16 }}>
        <h3 style={{ marginTop: 0 }}>ডেটা সিঙ্ক</h3>
        <p style={{ color: "var(--ink2)", fontSize: "14.5px" }}>ডেটা এখন এই ব্রাউজারেই থাকে। সিঙ্ক করতে নিচের বোতামটি চাপুন।</p>
        {syncMsg && <p style={{ color: "var(--ink2)", fontSize: "14.5px" }}>{syncMsg}</p>}
        <button className="btn btn-brand btn-sm" onClick={doSync}>সিঙ্ক করুন</button>
      </div>
      <div className="card">
        <h3 style={{ marginTop: 0 }}>ডেটা ও ব্যাকআপ</h3>
        <p style={{ color: "var(--ink2)", fontSize: "14.5px" }}>ডেটা এই ব্রাউজার ট্যাবের মেমরিতে থাকে — ট্যাব বন্ধ করলে সেগুলো মুছে যাবে। ব্যাকআপ ডাউনলোড করে রাখুন, পরে আপলোড করে ফিরিয়ে আনতে পারবেন।</p>
        <div style={{ display: "flex", gap: 9, flexWrap: "wrap", marginBottom: 12 }}>
          <button className="btn btn-ghost btn-sm" onClick={downloadBackup}>ব্যাকআপ ডাউনলোড (JSON)</button>
          <label className="btn btn-ghost btn-sm" style={{ margin: 0 }}>ব্যাকআপ আপলোড<input type="file" accept="application/json" style={{ display: "none" }} onChange={importBackup} /></label>
        </div>
        <div style={{ display: "flex", gap: 9, flexWrap: "wrap" }}>
          <button className="btn btn-accent btn-sm" onClick={() => { const d = sampleData(); setData(d); setF(d.settings); toast("নমুনা তথ্য বসানো হয়েছে"); }}>এক ক্লিকে নমুনা তথ্য বসান</button>
          <button className="btn btn-danger btn-sm" onClick={() => { const d = emptyData(); setData(d); setF(d.settings); toast("সব তথ্য মোছা হয়েছে"); }}>সব তথ্য মুছে ফেলুন</button>
        </div>
      </div>
    </div>
  );
}

/* ================================================================
   মূল App — ভিউ বদল, লগইন অবস্থা, টোস্ট
================================================================ */
function App() {
  const [data, setData] = useState(emptyData());
  const [view, setView] = useState("landing"); // landing | console
  const [user, setUser] = useState(null);
  const [loginOpen, setLoginOpen] = useState(false);
  const [admissionOpen, setAdmissionOpen] = useState(false);
  const [toastMsg, setToastMsg] = useState(null);
  const toastTimer = useRef(null);
  const toast = (msg, isErr) => {
    setToastMsg({ msg, isErr: !!isErr });
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToastMsg(null), 3400);
  };


  const onLogin = u => { setUser(u); setLoginOpen(false); setView("console"); toast(u.isSuper ? "স্বাগতম, সুপার অ্যাডমিন!" : "স্বাগতম! লগইন সফল (ডেমো)"); };
  const submitAdmission = f => {
    setData(prev => ({ ...prev, admissions: [...prev.admissions, { ...f, id: uid(), status: "pending", date: todayStr() }] }));
    setAdmissionOpen(false);
    toast("আবেদন জমা হয়েছে — স্কুল কর্তৃপক্ষ যাচাই করবে");
  };
  return (
    <div>
      {view === "landing"
        ? <Landing data={data} goConsole={() => setView("console")} openLogin={() => setLoginOpen(true)} openAdmission={() => setAdmissionOpen(true)} toast={toast} />
        : <Console data={data} setData={setData} user={user} toast={toast}
            goLanding={() => setView("landing")}
            logout={() => { setUser(null); setView("landing"); toast("লগআউট হয়েছে"); }} />}
      {loginOpen && <LoginModal close={() => setLoginOpen(false)} onLogin={onLogin} />}
      {admissionOpen && <AdmissionModal close={() => setAdmissionOpen(false)} submit={submitAdmission} showCost={data.settings.showYearlyCostAtAdmission !== false} costTypes={costTypesOf(data)} />}
      {toastMsg && <div className={"toast" + (toastMsg.isErr ? " err" : "")}>{toastMsg.msg}</div>}
    </div>
  );
}

export default App;
